INSERT INTO "Section" (id, title, description, slug, icon, "sortOrder", "isActive") VALUES
  ('sec-hospitality-reset', 'The Ditch Hospitality Reset', 'Every guest. Every shift. Every Ditch.', 'hospitality-reset', '', 10, true),
  ('sec-leadership-operating-system', 'Hospitality Leadership Operating System', 'Build the culture. Train the standard. Lead the shift.', 'leadership-operating-system', '', 20, true),
  ('sec-daily-masterminds', 'Daily Masterminds', 'One behavior. Repeated. Coached live. Reinforced after the shift.', 'daily-masterminds', '', 30, true),
  ('sec-trainer-operating-system', 'The Trainer Operating System', 'Train the trainers. Build culture carriers. Certify the standard.', 'trainer-operating-system', '', 40, true),
  ('sec-server-onboarding', 'Server Onboarding + Certification', 'Own the table''s experience from welcome through farewell.', 'server-onboarding', '', 50, true),
  ('sec-bartender-onboarding', 'Bartender Onboarding + Certification', 'Warm people. Cold drinks. Clean stations. Zero guessing.', 'bartender-onboarding', '', 60, true),
  ('sec-support-onboarding', 'Support Staff Onboarding + Certification', 'Protect welcome, accuracy, pace, cleanliness, and communication underneath the guest experience.', 'support-onboarding', '', 70, true)
