INSERT INTO "Module" (id, "sectionId", title, description, slug, content, "estimatedMinutes", "isRequired", "isActive", "sortOrder", tags) VALUES
  ('cur-reset-promise-care', 'sec-hospitality-reset', 'The Promise + Ditch CARE', 'Turn See It. Own It. Elevate It. into four observable moves every teammate can use.', 'promise-care', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-promise-care"><header><p class="curriculum-eyebrow">hospitality-reset / care / required</p><h1>The Promise + Ditch CARE</h1><p>Turn See It. Own It. Elevate It. into four observable moves every teammate can use.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>State the Ditch operating promise from memory.</li><li>Use CARE to choose the next useful action.</li><li>Explain how See It, Own It, and Elevate It map to the guest experience.</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Our operating promise</h2><p>Every guest leaves feeling seen, cared for, and genuinely glad they chose Ditch.</p></section><section class="curriculum-block curriculum-steps"><h2>Ditch CARE</h2><ol><li>C - Catch the Cue: notice the guest, room, teammate, timing, and next need.</li><li>A - Act With Ownership: take the next useful action instead of pointing, waiting, or saying it is not yours.</li><li>R - Resolve + Recover: close the loop, communicate early, and repair misses with care.</li><li>E - End Strong: verify the result, thank the guest sincerely, and create a clear reason to return.</li></ol></section><section class="curriculum-block curriculum-comparison"><h2>The operating language</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Phrase</th><th>Observable behavior</th></tr></thead><tbody><tr><td>See It</td><td>Catch the cue before the need becomes a complaint.</td></tr><tr><td>Own It</td><td>Act, resolve, or make a named handoff and verify it.</td></tr><tr><td>Elevate It</td><td>Personalize appropriately and end the moment stronger than it began.</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-practice"><h2>Cue-to-action sprint</h2><p>For five common guest or teammate cues, name the CARE move and the first observable action within five seconds.</p><h3>Success criteria</h3><ul><li>Names the cue</li><li>Chooses an owned action</li><li>Includes a closed loop</li><li>Avoids guessing or overpromising</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 80%; practical required.</p><ol><li><strong>multiple-choice</strong>: A guest is searching the room while you are carrying menus to another table. What is the first CARE move?</li><li><strong>practical</strong>: Respond to an arrival, an empty drink outside your section, and a delayed item using CARE.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 14, true, true, 10, ARRAY['hospitality-reset', 'care', 'required', 'practical-required']::text[]),
  ('cur-reset-baseline-magic', 'sec-hospitality-reset', 'Baseline First. Magic Second.', 'Protect reliable fundamentals before adding personalized, one-size-fits-one hospitality.', 'baseline-first-magic-second', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-baseline-magic"><header><p class="curriculum-eyebrow">hospitality-reset / baseline / guest-journey / required</p><h1>Baseline First. Magic Second.</h1><p>Protect reliable fundamentals before adding personalized, one-size-fits-one hospitality.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Separate the hospitality baseline from an elevated magic moment.</li><li>Protect accuracy, communication, safety, and clean resets under pressure.</li><li>Create personalization without sacrificing another guest&#039;s baseline.</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The governing rule</h2><p>A memorable gesture cannot compensate for an invisible arrival, inaccurate order, unsafe guess, silent delay, dirty station, or unfinished handoff. Reliability earns the right to personalize.</p></section><section class="curriculum-block curriculum-comparison"><h2>Baseline vs. magic</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Baseline - every guest</th><th>Magic - one size fits one</th></tr></thead><tbody><tr><td>Immediate acknowledgment and a full greet as soon as guest care allows</td><td>Use a remembered preference or occasion to shape the welcome</td></tr><tr><td>Accurate order, honest expectations, current product knowledge</td><td>Guide the guest toward a choice that fits their exact mood</td></tr><tr><td>Early updates, specific check-backs, closed handoffs</td><td>Remove a friction point before the guest notices it</td></tr><tr><td>Safe allergy and alcohol procedures; clean station and reset</td><td>Create an appropriate personal detail after the baseline is protected</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-steps"><h2>Guest journey baseline</h2><ol><li>Acknowledge immediately; a guest may wait during volume but should never feel invisible.</li><li>Learn the guest&#039;s reason, energy, appetite, pace, and needs.</li><li>Guide with one or two useful questions and one confident recommendation.</li><li>Communicate delays, 86s, timing, mistakes, and changes before frustration builds.</li><li>Check back specifically about temperature, flavor, spice, timing, or the corrected item.</li><li>Process payment promptly, thank the guest sincerely, and acknowledge the departure.</li></ol></section><section class="curriculum-block curriculum-scenario"><h2>Protect the baseline</h2><p>A regular wants a long conversation while a new party arrives and a kitchen bell sounds. Prioritize the next three actions and preserve warmth with everyone.</p><h3>Success criteria</h3><ul><li>Acknowledges the arrival</li><li>Answers or names the bell handoff</li><li>Pauses the regular naturally</li><li>Returns to close both loops</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 80%; practical required.</p><ol><li><strong>true-false</strong>: A personalized guest moment counts as great hospitality even if another arrival remains invisible.</li><li><strong>practical</strong>: Run the arrival/bell/regular scenario in under 45 seconds.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 16, true, true, 20, ARRAY['hospitality-reset', 'baseline', 'guest-journey', 'required', 'practical-required']::text[]),
  ('cur-reset-whole-room', 'sec-hospitality-reset', 'Every Guest Belongs to All of Us', 'Build five-foot awareness, team hospitality, urgency, and clean handoffs without confusion or scorekeeping.', 'whole-room-ownership', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-whole-room"><header><p class="curriculum-eyebrow">hospitality-reset / ownership / teamwork / required</p><h1>Every Guest Belongs to All of Us</h1><p>Build five-foot awareness, team hospitality, urgency, and clean handoffs without confusion or scorekeeping.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use the five-foot mentality</li><li>Make a named handoff</li><li>Help the room without abandoning the assigned role</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-green"><h2>The ownership rule</h2><p>If you see the need, acknowledge it. If you can solve it, solve it. If you cannot, make a named handoff and close the loop.</p></section><section class="curriculum-block curriculum-checklist"><h2>What beats low-priority work</h2><ul><li>Arrivals and waiting guests</li><li>Food in the pass, kitchen bells, and printed tickets</li><li>Empty drinks and dirty tables</li><li>Safety, spills, and allergy communication</li><li>A teammate approaching failure</li></ul></section><section class="curriculum-block curriculum-comparison"><h2>Ditch language</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Retire this</th><th>Use this</th></tr></thead><tbody><tr><td>That is not my table.</td><td>I can help, or I will grab the right person and make sure they come over.</td></tr><tr><td>Can someone run this?</td><td>Jordan, can you run this to 24? I will take 28.</td></tr><tr><td>I told them.</td><td>I handed it to Alex, Alex confirmed it, and I checked that it was done.</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-field-assignment"><h2>Five-foot floor proof</h2><p>During one shift, complete one unrequested teammate assist and repair three things simply because they entered your five feet.</p><h3>Success criteria</h3><ul><li>Help actually reduces friction</li><li>Normal responsibilities remain covered</li><li>Handoffs are named and confirmed</li><li>Manager records specific evidence</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 80%; practical required.</p><ol><li><strong>multiple-choice</strong>: A request you cannot personally complete is finished when...</li><li><strong>practical</strong>: Demonstrate a clean handoff for a waiting ticket, a guest request, and a spill.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 15, true, true, 30, ARRAY['hospitality-reset', 'ownership', 'teamwork', 'required', 'practical-required']::text[]),
  ('cur-reset-passion-selling', 'sec-hospitality-reset', 'Passion Selling: Guide, Do Not Push', 'Use observation and product knowledge to reduce uncertainty and help a guest choose what fits.', 'passion-selling', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-passion-selling"><header><p class="curriculum-eyebrow">hospitality-reset / passion-selling / menu / required</p><h1>Passion Selling: Guide, Do Not Push</h1><p>Use observation and product knowledge to reduce uncertainty and help a guest choose what fits.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use the five-step Passion Selling formula</li><li>Ask one useful preference question</li><li>Give a truthful sensory recommendation with a point of view</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Observe &gt; Ask &gt; Interpret &gt; Recommend &gt; Describe</h2><ol><li>Observe: notice appetite, pace, occasion, flavor clues, and how much guidance the guest wants.</li><li>Ask: use one or two efficient questions - bright or rich, mild or spicy, citrus or smoky, spirit-forward or zero proof.</li><li>Interpret: turn the answer into direction instead of repeating the whole menu.</li><li>Recommend: take a position - &#039;For what you described, I would go with...&#039;.</li><li>Describe: use truthful texture, flavor, contrast, fit, and a reason to care.</li></ol></section><section class="curriculum-block curriculum-comparison"><h2>From order taking to guidance</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Avoid</th><th>Better</th></tr></thead><tbody><tr><td>Everything is good.</td><td>Tell me what sounds better tonight - bright and lighter or rich and comforting?</td></tr><tr><td>Do you want an appetizer?</td><td>Before we get into mains, there are two shareables I would not want you to miss.</td></tr><tr><td>Would you like another drink?</td><td>I can keep you in this same lane or take you somewhere different - what sounds good?</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-menu-reference"><h2>Current practice set</h2><p>Use current descriptions and verified flavor lanes. Do not add ingredients, allergy claims, or availability from memory.</p><ul><li><strong>Yuca Poppers</strong> <span>$14</span><p>Fried yuca croquettes with guacamole, sweet chili, herb aioli, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Jerk Shrimp Taco</strong> <span>$5</span><p>Spicy slaw, pico de gallo, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Lobster Roll</strong> <span>$35</span><p>Hot: warm and buttery. Cold: tossed in herb aioli. Served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Zuma Beach Bowl</strong> <span>$21</span><p>Quinoa, vegetable medley, crunchy chickpeas, pickled onions, and lemon-basil vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Hang 10 Marg</strong> <span>$13.24</span><p>Reposado tequila, orange liqueur, fresh lime and lemon juices, house sugar syrup, and a salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Smoke on the Bay</strong> <span>$14.78</span><p>Tanteo Chipotle, 400 Conejos mezcal, fresh lime, watermelon, house sugar syrup, and a black lava salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Pineapple Basil Smash</strong> <span>$14.78</span><p>Reposado tequila, basil, cucumber, pineapple, and fresh lemon juice.</p><p><small>Source status: approved</small></p></li><li><strong>Watermelon Cooler</strong> <span>$6.18</span><p>Watermelon, fresh lime, pineapple juice, and mint.</p><p><small>Source status: approved</small></p></li></ul></section><section class="curriculum-block curriculum-practice"><h2>The twenty-second challenge</h2><p>Ask one preference question, recommend one current item, explain why it fits, and set one honest expectation in twenty seconds.</p><h3>Success criteria</h3><ul><li>Learns a real preference</li><li>Takes a clear position</li><li>Uses truthful sensory language</li><li>Avoids pressure and ingredient dumping</li><li>Uses only current source facts</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 80%; practical required.</p><ol><li><strong>multi-select</strong>: Which behaviors belong in Passion Selling?</li><li><strong>practical</strong>: Guide three profiles: first-time sharer, guest wanting bright/not sweet, and guest wanting a filling meal.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, food-menu-supplied, cocktail-menu-supplied, bar-manual-2026-08</small></footer></article>$curriculum_html$, 22, true, true, 40, ARRAY['hospitality-reset', 'passion-selling', 'menu', 'required', 'practical-required']::text[]),
  ('cur-reset-source-safety', 'sec-hospitality-reset', 'Never Guess: Source Discipline + Safety', 'Know where current truth lives and stop before an uncertain allergy, recipe, beer, or policy answer becomes guest risk.', 'source-discipline-allergy-safety', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-source-safety"><header><p class="curriculum-eyebrow">hospitality-reset / safety / allergy / source-control / required</p><h1>Never Guess: Source Discipline + Safety</h1><p>Know where current truth lives and stop before an uncertain allergy, recipe, beer, or policy answer becomes guest risk.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use approved sources instead of memory</li><li>Execute the allergy communication chain</li><li>Identify verification-required and rotating menu content</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-warning"><h2>Accuracy is hospitality</h2><p>If you are unsure, say: &#039;Let me confirm that so I give you the right answer.&#039; Never guess on allergies, alcohol service, a recipe, or an unfamiliar current product.</p></section><section class="curriculum-block curriculum-steps"><h2>Allergy communication chain</h2><ol><li>Acknowledge the concern without promising an outcome</li><li>Mark it using the current POS procedure</li><li>Communicate it verbally</li><li>Involve the manager</li><li>Allow the kitchen to confirm what can be prepared safely</li><li>Confirm the approved delivery/handoff</li></ol></section><section class="curriculum-block curriculum-source-control curriculum-status-verification-required"><h2>Verification-required content</h2><p>Do not certify allergy specifics from menu descriptions. Do not train Ancho Average, Sunburnt Summer, Frozen Paloma, Da Painkiller, Island Rum Punch, or Hibiscus Refresher until the recipe lock is approved. Pink salt, wine-pour, and par conflicts also remain manager verification items.</p><p><small>Sources: allergy-source-current, bar-manual-2026-08</small></p></section><section class="curriculum-block curriculum-source-control curriculum-status-rotating"><h2>Rotating beer</h2><p>Beer selections change by location and date. Demonstrate how to verify the live POS/posted list; do not memorize a historic fixed list as permanent truth.</p><p><small>Sources: beer-source-current</small></p></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>multiple-choice</strong>: A guest asks whether a dish is safe for a serious allergy and you remember an ingredient list. What should you do?</li><li><strong>practical</strong>: Handle an allergy question, an unavailable beer question, and a recipe conflict.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, bar-manual-2026-08, allergy-source-current, beer-source-current</small></footer></article>$curriculum_html$, 16, true, true, 50, ARRAY['hospitality-reset', 'safety', 'allergy', 'source-control', 'required', 'practical-required']::text[]),
  ('cur-reset-last', 'sec-hospitality-reset', 'L.A.S.T. Guest Recovery', 'Repair trust, own the problem, follow up personally, and improve the system behind the miss.', 'last-recovery', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-last"><header><p class="curriculum-eyebrow">hospitality-reset / recovery / last / required</p><h1>L.A.S.T. Guest Recovery</h1><p>Repair trust, own the problem, follow up personally, and improve the system behind the miss.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use Listen, Apologize, Solve, Think</li><li>Keep same-team language</li><li>Follow up and identify the system lesson</li></ul></section><section class="curriculum-block curriculum-steps"><h2>L.A.S.T.</h2><ol><li>Listen: hear the complete concern and summarize what the guest actually cares about.</li><li>Apologize: acknowledge the experience without excuses, blame, or a defensive &#039;but&#039;.</li><li>Solve: take meaningful action; own the issue until it is solved or physically and verbally transferred.</li><li>Think: after the guest is cared for, capture what allowed the miss and how the system should improve.</li></ol></section><section class="curriculum-block curriculum-comparison"><h2>Same-team recovery language</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Avoid</th><th>Use</th></tr></thead><tbody><tr><td>The kitchen messed it up.</td><td>We missed that. I am getting it corrected right now.</td></tr><tr><td>We are slammed.</td><td>Thank you for waiting. I have you, and I am getting an update now.</td></tr><tr><td>That is our policy.</td><td>Here is what I can do. Let me confirm the best next step with my manager.</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-script"><h2>A human recovery</h2><p>Use the structure without sounding like an acronym.</p><blockquote><p>You are right to be frustrated.</p><p>Let me take care of this with you.</p><p>I will come back personally to make sure we got it right.</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Recovery reps</h2><p>Run a cold item, a long wait, and a correctly made item the guest simply dislikes.</p><h3>Success criteria</h3><ul><li>Listens without interruption</li><li>No blame or excuses</li><li>Solution fits the concern and role boundary</li><li>Follows up</li><li>Names a system lesson</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: When does the Think step happen?</li><li><strong>practical</strong>: Complete one surprise recovery from first sentence through follow-up and system lesson.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, leadership-os-1</small></footer></article>$curriculum_html$, 20, true, true, 60, ARRAY['hospitality-reset', 'recovery', 'last', 'required', 'practical-required']::text[]),
  ('cur-reset-accountability', 'sec-hospitality-reset', 'How We Work Here: Professionalism + Accountability', 'Make readiness, communication, coachability, checklists, resets, and follow-through observable.', 'professionalism-accountability', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-accountability"><header><p class="curriculum-eyebrow">hospitality-reset / accountability / professionalism / required</p><h1>How We Work Here: Professionalism + Accountability</h1><p>Make readiness, communication, coachability, checklists, resets, and follow-through observable.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Describe the ready-to-work standard</li><li>Receive coaching with Heard and act</li><li>Explain how performance and schedules connect</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Observable operating standards</h2><ul><li>Arrive on time, in uniform, with coffee, food, and personal tasks handled.</li><li>Keep phones away and out of guest view unless the MOD approves a specific use.</li><li>Use professional language: no profanity, gossip, arguing, sexual or inappropriate conversation, panic, blame, or personal drama.</li><li>Check 7shifts before work; a read receipt means the instruction was received and must be followed.</li><li>Complete and honestly verify opening, handoff, closing, weekly cleaning, PAR, and sidework sheets.</li><li>Count first; cover, label on tape, date, FIFO, and return product to its assigned location.</li><li>Leave the complete station ready for the next shift.</li></ul></section><section class="curriculum-block curriculum-script"><h2>Receive coaching cleanly</h2><blockquote><p>Heard.</p><p>Make the immediate correction.</p><p>If needed after the reset: &#039;Fixed. Can you show me what you want next time so I hit it consistently?&#039;</p></blockquote></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>What accountability means</h2><p>Great behavior is recognized specifically. Misses are redirected in real time. Recurring patterns, false sign-offs, ignored direction, or repeated failure to close loops are documented and coached. Schedules reflect business needs and demonstrated reliability, hospitality, pace, teamwork, knowledge, follow-through, and coachability.</p></section><section class="curriculum-block curriculum-field-assignment"><h2>One-week commitment</h2><p>Choose one observable behavior to improve for seven days and capture floor evidence every shift.</p><h3>Success criteria</h3><ul><li>Behavior is specific</li><li>Manager can observe it</li><li>Employee receives coaching without a courtroom</li><li>Evidence shows whether it changed</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 80%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the first response to a valid in-the-moment correction?</li><li><strong>practical</strong>: Receive a station-reset correction, act, and ask one useful clarification after the immediate need is protected.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 18, true, true, 70, ARRAY['hospitality-reset', 'accountability', 'professionalism', 'required', 'practical-required']::text[]),
  ('cur-reset-live-certification', 'sec-hospitality-reset', 'Hospitality Reset: Live Floor Certification', 'Prove the reset through live behavior, not attendance or vocabulary.', 'hospitality-reset-live-certification', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-reset-live-certification"><header><p class="curriculum-eyebrow">hospitality-reset / certification / live-observation / required</p><h1>Hospitality Reset: Live Floor Certification</h1><p>Prove the reset through live behavior, not attendance or vocabulary.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Execute the baseline during live service</li><li>Create one appropriate magic moment</li><li>Receive coaching and improve on a second take</li></ul></section><section class="curriculum-block curriculum-outcomes"><h2>Certification proof</h2><ul><li>Immediate acknowledgment</li><li>Guest discovery and confident guidance</li><li>Current-source discipline</li><li>Whole-room ownership and clean handoffs</li><li>Early communication and specific check-back</li><li>Professional coaching response</li><li>Strong close</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Observed service block</h2><p>A qualified trainer observes a realistic service block and records specific evidence for every baseline behavior plus one personalized moment.</p><h3>Success criteria</h3><ul><li>No critical safety or integrity miss</li><li>Baseline appears consistently</li><li>Magic does not steal from another guest</li><li>One coached miss improves on the second take</li><li>Trainer records evidence, not personality labels</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>short-answer</strong>: Teach back CARE, Baseline First. Magic Second., Passion Selling, and L.A.S.T. in your own words.</li><li><strong>practical</strong>: Complete the observed service block.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 30, true, true, 80, ARRAY['hospitality-reset', 'certification', 'live-observation', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-0', 'sec-leadership-operating-system', 'Week 0 - Culture Calibration', 'Name the culture that actually exists before trying to improve it.', 'culture-calibration', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-0"><header><p class="curriculum-eyebrow">leadership-os / week-0 / leadership-lab / required</p><h1>Week 0 - Culture Calibration</h1><p>Name the culture that actually exists before trying to improve it.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Score observable behavior rather than intentions, personalities, or the restaurant&#039;s best night.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Aspirational language cannot repair tolerated behavior. Honest calibration gives leadership one shared starting point.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Use specific floor evidence, agree on the largest gaps, and choose a small number of behaviors to stop tolerating immediately.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Scores include observed examples</li><li>Leaders name three priority gaps</li><li>One behavior to stop and one behavior to celebrate are selected</li><li>The first reset has an owner</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>What behavior currently survives here?</p><p>What would a new employee copy after three shifts?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Compare Culture Audit scores. For every score that differs by more than two points, each leader provides one observed example.</p><h3>Success criteria</h3><ul><li>Completed audit</li><li>Three priority gaps</li><li>One behavior to stop</li><li>One behavior to celebrate</li><li>Leadership agreement on first reset</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Observe one full shift across standards, accountability, hospitality, team hospitality, ownership, selling, recovery, systems, coaching, and training.</p><h3>Success criteria</h3><ul><li>Completed audit</li><li>Three priority gaps</li><li>One behavior to stop</li><li>One behavior to celebrate</li><li>Leadership agreement on first reset</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Inflated scores</li><li>Blame</li><li>Vague labels such as bad attitude</li><li>Treating a system failure as a character flaw</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What makes a Culture Audit score usable?</li><li><strong>practical</strong>: Compare Culture Audit scores. For every score that differs by more than two points, each leader provides one observed example.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 75, true, true, 10, ARRAY['leadership-os', 'week-0', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-1', 'sec-leadership-operating-system', 'Week 1 - Leadership Identity', 'Make leadership behavior the clearest training tool in the building.', 'leadership-identity', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-1"><header><p class="curriculum-eyebrow">leadership-os / week-1 / leadership-lab / required</p><h1>Week 1 - Leadership Identity</h1><p>Make leadership behavior the clearest training tool in the building.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Model before mandating, inspect what you expect, coach what you inspect, and reinforce what improves.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>The team studies what leaders model, ignore, reinforce, and repeat. A leader is always training.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Be visible, calm, willing to help, quick to own misses, and consistent when the room gets busy.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Leader demonstrates before demanding</li><li>Misses are inspected and coached</li><li>Improvement is recognized specifically</li><li>Leader owns a contradiction quickly</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>Watch me once. Run it with me once. Now show me the standard without me.</p><p>What did the team learn from watching me in that moment?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Replay a leader walking past a miss, then replay it with modeling, coaching, and specific recognition.</p><h3>Success criteria</h3><ul><li>Seven completed reflections</li><li>One live observation</li><li>Evidence of model, inspect, coach, reinforce</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>For seven shifts, capture one moment when leadership behavior reinforced or contradicted the culture.</p><h3>Success criteria</h3><ul><li>Seven completed reflections</li><li>One live observation</li><li>Evidence of model, inspect, coach, reinforce</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Demanding standards the leader does not follow</li><li>Correction without demonstration</li><li>Administrative hiding</li><li>Vague recognition</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which sequence is the leadership standard?</li><li><strong>practical</strong>: Replay a leader walking past a miss, then replay it with modeling, coaching, and specific recognition.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 75, true, true, 20, ARRAY['leadership-os', 'week-1', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-2', 'sec-leadership-operating-system', 'Week 2 - Standards Without Ego', 'Create fast, neutral accountability through the 10 for 10 reset and the no-ego response.', 'standards-without-ego', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-2"><header><p class="curriculum-eyebrow">leadership-os / week-2 / leadership-lab / required</p><h1>Week 2 - Standards Without Ego</h1><p>Create fast, neutral accountability through the 10 for 10 reset and the no-ego response.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Anyone may protect the standard. The first response to correction is Heard, followed by action.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Small disorder compounds. Emotional correction teaches defense instead of protecting the standard.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Notice drift early, call a neutral reset, join the work, verify completion, recognize the reset, and move on without theater.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>10 for 10 lasts roughly 30 seconds</li><li>Anyone can call it</li><li>Leader participates</li><li>Completion is verified and released</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>10 for 10, team. Thirty-second reset.</p><p>Beautiful - that is our standard. Let&#039;s go.</p><p>Heard. Fixed. Can you show me what you want next time?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Create five minor station misses. Identify drift, call the reset, participate, recognize completion, and release the team.</p><h3>Success criteria</h3><ul><li>Calls and executes a live reset</li><li>Receives a reset with Heard</li><li>Coaches without creating defensiveness</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Use 10 for 10 only when the environment is drifting and verify that the reset is actually complete.</p><h3>Success criteria</h3><ul><li>Calls and executes a live reset</li><li>Receives a reset with Heard</li><li>Coaches without creating defensiveness</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Using the phrase as punishment</li><li>Calling it without helping</li><li>Public embarrassment</li><li>Sarcasm</li><li>Courtroom explanations</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the purpose of 10 for 10?</li><li><strong>practical</strong>: Create five minor station misses. Identify drift, call the reset, participate, recognize completion, and release the team.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 80, true, true, 30, ARRAY['leadership-os', 'week-2', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-3', 'sec-leadership-operating-system', 'Week 3 - Unconditional Hospitality', 'Turn awareness into action for guests and coworkers regardless of mood or pressure.', 'unconditional-hospitality', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-3"><header><p class="curriculum-eyebrow">leadership-os / week-3 / leadership-lab / required</p><h1>Week 3 - Unconditional Hospitality</h1><p>Turn awareness into action for guests and coworkers regardless of mood or pressure.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Notice what a person needs, make it easier, personalize where possible, and act before they have to ask.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Hospitality is felt in small moments of anticipation. When it depends on an easy guest or shift, it is not a standard.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Read the room, remove friction, match the guest&#039;s preferred pace, and give teammates unrequested support.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Reads quiet and verbal cues</li><li>Acts before being asked</li><li>Matches pace without disappearing</li><li>Team help is useful and unscored</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>What can I make better within the next five feet?</p><p>What can we solve before they ask?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>For five guest scenarios, identify the need, friction, personal detail, and anticipatory action.</p><h3>Success criteria</h3><ul><li>Three live anticipation examples</li><li>At least one coworker example</li><li>Trainer records the cue and action</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Log three anticipated needs, two coworker hospitality moments, and one personalized guest experience.</p><h3>Success criteria</h3><ul><li>Three live anticipation examples</li><li>At least one coworker example</li><li>Trainer records the cue and action</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Robotic scripts</li><li>Over-talking</li><li>Helping only favorite coworkers</li><li>Missing quiet signals</li><li>Confusing speed with care</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What converts awareness into hospitality?</li><li><strong>practical</strong>: For five guest scenarios, identify the need, friction, personal detail, and anticipatory action.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 75, true, true, 40, ARRAY['leadership-os', 'week-3', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-4', 'sec-leadership-operating-system', 'Week 4 - Passion Selling', 'Teach confident, personal recommendations that increase guest value without pressure.', 'passion-selling-leadership', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-4"><header><p class="curriculum-eyebrow">leadership-os / week-4 / leadership-lab / required</p><h1>Week 4 - Passion Selling</h1><p>Teach confident, personal recommendations that increase guest value without pressure.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Observe, ask, interpret, recommend, and describe; take a position based on the guest rather than reciting the menu.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Guests gain value when knowledgeable employees reduce uncertainty. Revenue follows trust, relevance, and genuine enthusiasm.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Ask one useful preference question, recommend with confidence, use contrast, describe the experience, and offer a natural pairing.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Recommendation fits the clue</li><li>Description is sensory and truthful</li><li>Contrast sets expectations</li><li>No ingredient dump or automatic add-on</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>For what you just described, I would absolutely send you toward...</p><p>Are you leaning brighter and lighter or richer and more comforting?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Sell one current item without good, delicious, or amazing and without listing ingredients; explain who would love it and who might not.</p><h3>Success criteria</h3><ul><li>Trains one teammate</li><li>Three successful role plays</li><li>One observed live recommendation</li><li>Uses current menu facts</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Make three preference-based recommendations and record the question, recommendation, and guest response.</p><h3>Success criteria</h3><ul><li>Trains one teammate</li><li>Three successful role plays</li><li>One observed live recommendation</li><li>Uses current menu facts</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Everything is good</li><li>Ingredient dumping</li><li>Fake enthusiasm</li><li>Automatic add-ons</li><li>Recommending before learning</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What should happen before a recommendation?</li><li><strong>practical</strong>: Sell one current item without good, delicious, or amazing and without listing ingredients; explain who would love it and who might not.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 85, true, true, 50, ARRAY['leadership-os', 'week-4', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-5', 'sec-leadership-operating-system', 'Week 5 - Guest Recovery', 'Use L.A.S.T. to care for the guest and improve the system behind the miss.', 'guest-recovery', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-5"><header><p class="curriculum-eyebrow">leadership-os / week-5 / leadership-lab / required</p><h1>Week 5 - Guest Recovery</h1><p>Use L.A.S.T. to care for the guest and improve the system behind the miss.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Listen, Apologize, Solve, Think; own the problem until it is solved or physically and verbally transferred.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>A comp may correct a check, but recovery has to repair trust. The response can become more memorable than the miss.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Listen without defense, acknowledge the experience, offer a meaningful solution, follow up personally, and capture the cause.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>No excuses or blame</li><li>Solution fits the concern</li><li>Guest receives a specific follow-up</li><li>System lesson has an owner</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>You are right to be frustrated.</p><p>Let me take care of this with you.</p><p>I will come back to make sure we got it right.</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Run recovery scenarios and score listening, ownership, solution quality, same-team language, follow-up, and system thinking.</p><h3>Success criteria</h3><ul><li>Three simulated recoveries</li><li>One live or case-based recovery</li><li>Follow-up</li><li>System improvement</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Use the recovery log for every meaningful recovery and complete Think after the guest is cared for.</p><h3>Success criteria</h3><ul><li>Three simulated recoveries</li><li>One live or case-based recovery</li><li>Follow-up</li><li>System improvement</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Excuses</li><li>Department blame</li><li>Policy shields</li><li>Arguing facts</li><li>Disappearing after the solution</li><li>Compensation without care</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What does L.A.S.T. stand for?</li><li><strong>practical</strong>: Run recovery scenarios and score listening, ownership, solution quality, same-team language, follow-up, and system thinking.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 85, true, true, 60, ARRAY['leadership-os', 'week-5', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-6', 'sec-leadership-operating-system', 'Week 6 - Accountability + Coaching', 'Correct observable behavior without ego, labels, humiliation, or delayed ambiguity.', 'accountability-coaching', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-6"><header><p class="curriculum-eyebrow">leadership-os / week-6 / leadership-lab / required</p><h1>Week 6 - Accountability + Coaching</h1><p>Correct observable behavior without ego, labels, humiliation, or delayed ambiguity.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use observation, standard, impact, reset, and confirmation to make the next rep more likely to succeed.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Clear, timely behavioral coaching protects the guest and gives the employee a usable path forward.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Coach facts rather than identity; diagnose clarity, skill, system, environment, and willingness before choosing the response.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Correction is timely and specific</li><li>Impact is connected to guest/team/safety</li><li>One reset behavior is named</li><li>Second-take evidence is captured</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>Here is what I observed...</p><p>Our standard is...</p><p>Why that matters is...</p><p>What I need from you now is...</p><p>We are aligned?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Convert five vague labels into observable coaching statements, then deliver a 60-second coach and require a second take.</p><h3>Success criteria</h3><ul><li>Behavioral observation</li><li>Correct standard</li><li>One clear reset</li><li>Second-take improvement</li><li>Appropriate privacy/urgency decision</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Use one timely 60-second coach and one Keep / Start / Stop debrief during a real shift.</p><h3>Success criteria</h3><ul><li>Behavioral observation</li><li>Correct standard</li><li>One clear reset</li><li>Second-take improvement</li><li>Appropriate privacy/urgency decision</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Always and never</li><li>Personality labels</li><li>Public humiliation</li><li>Saving everything for later</li><li>Retraining a willingness problem</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which opening is behavioral coaching?</li><li><strong>practical</strong>: Convert five vague labels into observable coaching statements, then deliver a 60-second coach and require a second take.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 85, true, true, 70, ARRAY['leadership-os', 'week-6', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-7', 'sec-leadership-operating-system', 'Week 7 - 80/20 Resourcefulness', 'Develop people who think, act, and bring recommendations upward.', 'resourcefulness-80-20', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-7"><header><p class="curriculum-eyebrow">leadership-os / week-7 / leadership-lab / required</p><h1>Week 7 - 80/20 Resourcefulness</h1><p>Develop people who think, act, and bring recommendations upward.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Clarify facts, identify what is controllable, create options, take the next-best action, and recommend a move.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>Automatic escalation creates helplessness and leader bottlenecks. Resourcefulness separates the real constraint from the story around it.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Raise problems early with actions already taken, available options, and a recommendation; never hide safety or urgency.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>Facts are separated from emotion</li><li>Controllables are named</li><li>Three options are considered</li><li>A recommendation is brought upward</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>What have you tried?</p><p>What can you control?</p><p>What is the next-best move?</p><p>What are you recommending?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Give a common roadblock with one fixed constraint; produce three controllable actions and a recommendation in 60 seconds.</p><h3>Success criteria</h3><ul><li>One employee coached through the full 80/20 worksheet</li><li>Sound recommendation</li><li>Appropriate action and escalation</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>When a problem is escalated, coach the thinking before supplying the answer unless guest safety or urgency requires direction.</p><h3>Success criteria</h3><ul><li>One employee coached through the full 80/20 worksheet</li><li>Sound recommendation</li><li>Appropriate action and escalation</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Hiding problems</li><li>Reckless improvisation</li><li>Learned helplessness</li><li>Leaders answering too quickly</li><li>Withholding support</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What should an employee bring upward with a non-urgent problem?</li><li><strong>practical</strong>: Give a common roadblock with one fixed constraint; produce three controllable actions and a recommendation in 60 seconds.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 75, true, true, 80, ARRAY['leadership-os', 'week-7', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-leadership-week-8', 'sec-leadership-operating-system', 'Week 8 - Systems + Predictability', 'Convert repeated problems into owned, visible, testable systems.', 'systems-predictability', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-leadership-week-8"><header><p class="curriculum-eyebrow">leadership-os / week-8 / leadership-lab / required</p><h1>Week 8 - Systems + Predictability</h1><p>Convert repeated problems into owned, visible, testable systems.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Define the standard, owner, trigger, method, verification, and recovery for every critical system.</li><li>Teach the standard to another leader</li><li>Produce live floor evidence</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Why it matters</h2><p>If the same capable people fail the same process, another reminder is not a solution. Mature operations learn from repetition.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The standard</h2><p>Build processes that survive a manager&#039;s absence, make completion visible, and improve after breakdown.</p></section><section class="curriculum-block curriculum-checklist"><h2>What great looks like</h2><ul><li>One named owner</li><li>A clear trigger</li><li>Method and resources are defined</li><li>Verification is visible</li><li>Recovery path exists</li></ul></section><section class="curriculum-block curriculum-script"><h2>Leader language</h2><blockquote><p>What system is allowing this result?</p><p>Who owns it, what triggers it, and how do we verify completion?</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Run the drill</h2><p>Build a six-part system for one recurring problem, hand it to another leader, and test it without extra explanation.</p><h3>Success criteria</h3><ul><li>One real system built</li><li>Named owner and verification</li><li>Test completed</li><li>Revision based on evidence</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>On the floor</h2><p>Capture one repeated failure, diagnose person versus system, and test one improvement during the week.</p><h3>Success criteria</h3><ul><li>One real system built</li><li>Named owner and verification</li><li>Test completed</li><li>Revision based on evidence</li></ul></section><section class="curriculum-block curriculum-bullets"><h2>Watch for</h2><ul><li>Everyone owns it</li><li>No trigger</li><li>Hidden completion</li><li>Missing resources</li><li>Constant exceptions</li><li>Systems living only in a manager&#039;s head</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which element proves a system happened correctly?</li><li><strong>practical</strong>: Build a six-part system for one recurring problem, hand it to another leader, and test it without extra explanation.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 90, true, true, 90, ARRAY['leadership-os', 'week-8', 'leadership-lab', 'required', 'practical-required']::text[]),
  ('cur-mastermind-unconditional-hospitality', 'sec-daily-masterminds', 'Cycle 1 - Unconditional Hospitality', 'Awareness, anticipation, and care. Ten shifts, one five-minute behavior rep per shift.', 'mastermind-unconditional-hospitality', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-mastermind-unconditional-hospitality"><header><p class="curriculum-eyebrow">daily-mastermind / cycle-1 / leadership / floor-training</p><h1>Cycle 1 - Unconditional Hospitality</h1><p>Awareness, anticipation, and care. Ten shifts, one five-minute behavior rep per shift.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Run all ten pre-shift sessions in sequence.</li><li>Observe and coach each day&#039;s behavior during live service.</li><li>Repeat a day when behavior has not transferred to the floor.</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Cycle standard</h2><p>Name the behavior in pre-shift, observe it during service, coach or reinforce it live, and close the loop after the shift.</p></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 1: What Hospitality Actually Means</h2><p>Intention, not generic niceness. Niceness is a pleasant attitude. Hospitality notices something specific and improves another person&#039;s experience because of it. Example: A warm welcome becomes hospitality when the teammate also notices an accessibility need, makes space, and lets the guest settle.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - What Hospitality Actually Means</h2><p>What is the difference between being nice and creating hospitality? Name one polite action and upgrade it into an intentional hospitality action.</p><h3>Success criteria</h3><ul><li>Specific clues noticed</li><li>Action is personal rather than performative</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Make one guest or coworker feel specifically seen.</p><h3>Success criteria</h3><ul><li>Specific clues noticed</li><li>Action is personal rather than performative</li><li>Close with: Who felt specifically seen because of something we did?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 2: Anticipation</h2><p>Solve the next need before the ask. Anticipation reads timing, body language, table context, and the predictable next need; it is not mind reading. Example: A family organizing bags while food arrives gets extra space and napkins before the first spill.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Anticipation</h2><p>What can we solve tonight before someone asks? Call out three guest clues; name the most useful next action for each.</p><h3>Success criteria</h3><ul><li>Cue seen but ignored</li><li>Help arrives at a useful time</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Create one anticipated-need moment in every section.</p><h3>Success criteria</h3><ul><li>Cue seen but ignored</li><li>Help arrives at a useful time</li><li>Close with: What did we solve before the guest had to ask?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 3: Coworker Hospitality</h2><p>Give the team the care we promise guests. Hospitality moves in every direction. Useful, unrequested help protects the guest without creating debt or scorekeeping. Example: Run another section&#039;s food before it dies in the window.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Coworker Hospitality</h2><p>Would we tolerate ourselves treating a guest the way we sometimes treat each other? Name one unrequested assist your position can give another position.</p><h3>Success criteria</h3><ul><li>No sarcasm or scorekeeping</li><li>Employee still owns normal responsibilities</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Complete one unrequested assist that actually helps.</p><h3>Success criteria</h3><ul><li>No sarcasm or scorekeeping</li><li>Employee still owns normal responsibilities</li><li>Close with: Who made someone else&#039;s shift easier, and how?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 4: The Five-Foot Mentality</h2><p>Own the condition around you. Your title does not shrink your awareness. Improve what is unsafe, confusing, dirty, delayed, or emotionally unattended in your immediate environment. Example: A leader heading to the office fixes the crooked chair, empty glass, and confused guest that enter their five feet.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - The Five-Foot Mentality</h2><p>What problems exist because people walk past them? Scan the room for ten seconds and name the first useful improvement.</p><h3>Success criteria</h3><ul><li>Repeated walk-bys</li><li>Problems named without action or transfer</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Fix or connect every obvious issue that enters your five feet.</p><h3>Success criteria</h3><ul><li>Repeated walk-bys</li><li>Problems named without action or transfer</li><li>Close with: What did you fix simply because it entered your five feet?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 5: Names</h2><p>Use recognition naturally. A name tells someone they are not interchangeable. Use it naturally and accurately; recognition is not a forced script. Example: Jordan, can you run this to 24? Thank you - instead of a vague call to the room.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Names</h2><p>What happens when somebody remembers your name? Learn one useful detail from someone whose name or role you know least.</p><h3>Success criteria</h3><ul><li>Warmth and accuracy</li><li>Names are not used only for correction</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Learn and naturally use two names you do not normally use.</p><h3>Success criteria</h3><ul><li>Warmth and accuracy</li><li>Names are not used only for correction</li><li>Close with: Whose name did you learn or use differently?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 6: Reading the Guest</h2><p>Match the style of service to the table. Consistent care does not require identical delivery. Read verbal cues, eye contact, pace, occasion, and engagement. Example: A quiet conversation may need precise, low-interruption service; a celebratory group may welcome energy and guidance.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Reading the Guest</h2><p>Does every table want the same style of service? Act out two table styles; choose an opening approach and explain the cue.</p><h3>Success criteria</h3><ul><li>Over-talking or disappearing</li><li>Quiet guests still receive attention</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Identify each table&#039;s preferred service style and match it.</p><h3>Success criteria</h3><ul><li>Over-talking or disappearing</li><li>Quiet guests still receive attention</li><li>Close with: Which table needed a different version of you?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 7: Removing Friction</h2><p>Eliminate tiny inconveniences. Friction makes the guest or team work harder: missing items, late information, repeated questions, clutter, or awkward timing. Example: A guest with a deadline receives realistic menu guidance, kitchen communication, and a prepared check before anxiety builds.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Removing Friction</h2><p>What small inconvenience can we eliminate tonight? Name one friction point at arrival, ordering, dining, payment, and departure; choose one to remove.</p><h3>Success criteria</h3><ul><li>Recurring confusion</li><li>Workarounds that should become systems</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Remove one friction point and tell the manager what changed.</p><h3>Success criteria</h3><ul><li>Recurring confusion</li><li>Workarounds that should become systems</li><li>Close with: What became easier because we noticed it?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 8: Pace</h2><p>Use timing as a form of care. Observe before approaching. Good pace balances attentiveness with space and anticipates the table&#039;s next transition. Example: Let the guest take two bites before a specific check-back while a correction is still possible.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Pace</h2><p>Can great hospitality feel bad if the timing is wrong? Choose approach now, wait, or prepare silently for three table moments.</p><h3>Success criteria</h3><ul><li>Autopilot check-backs</li><li>Hovering or long disappearances</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Pause and read before every non-routine approach.</p><h3>Success criteria</h3><ul><li>Autopilot check-backs</li><li>Hovering or long disappearances</li><li>Close with: Where did better timing improve an interaction?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 9: Personalization</h2><p>Use the clue already offered. Personalization uses a shared occasion, preference, time constraint, or prior visit to shape one appropriate part of the experience. Example: A guest who loved a bright, not-too-sweet margarita receives a relevant current recommendation instead of the whole menu again.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Personalization</h2><p>What clue has the guest already given us? Use one guest clue to create a natural follow-through that does not feel invasive.</p><h3>Success criteria</h3><ul><li>Relevant and restrained</li><li>Does not feel like surveillance or a sales trick</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one real guest detail to personalize an experience.</p><h3>Success criteria</h3><ul><li>Relevant and restrained</li><li>Does not feel like surveillance or a sales trick</li><li>Close with: What detail made an experience feel less generic?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 10: Hospitality Story</h2><p>Turn great moments into culture. Specific recognition names the clue, the action, and why it mattered so the whole room can repeat it. Example: Not &#039;Sam crushed it&#039;; name the ferry-time clue, the pacing action, and the stress it removed.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Hospitality Story</h2><p>What did someone do during this cycle that deserves to be copied? Tell one 30-second story: what was noticed, what was done, and why it mattered.</p><h3>Success criteria</h3><ul><li>Specific behavior</li><li>Missing details are requested</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Create one final hospitality moment worth telling tomorrow.</p><h3>Success criteria</h3><ul><li>Specific behavior</li><li>Missing details are requested</li><li>Close with: Which behavior should become part of every shift?</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>short-answer</strong>: Name the behavior that changed, the floor evidence, and the behavior that still needs another cycle.</li><li><strong>practical</strong>: Deliver one surprise day from the cycle and show how it will be observed and reinforced during service.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 50, true, true, 10, ARRAY['daily-mastermind', 'cycle-1', 'leadership', 'floor-training', 'practical-required']::text[]),
  ('cur-mastermind-passion-selling', 'sec-daily-masterminds', 'Cycle 2 - Passion Selling', 'Confident, personal recommendations. Ten shifts, one five-minute behavior rep per shift.', 'mastermind-passion-selling', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-mastermind-passion-selling"><header><p class="curriculum-eyebrow">daily-mastermind / cycle-2 / leadership / floor-training</p><h1>Cycle 2 - Passion Selling</h1><p>Confident, personal recommendations. Ten shifts, one five-minute behavior rep per shift.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Run all ten pre-shift sessions in sequence.</li><li>Observe and coach each day&#039;s behavior during live service.</li><li>Repeat a day when behavior has not transferred to the floor.</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Cycle standard</h2><p>Use current sources and the full Observe &gt; Ask &gt; Interpret &gt; Recommend &gt; Describe formula without pressure or invention.</p></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 1: Beyond &#039;It&#039;s Good&#039;</h2><p>Describe why an item matters. Generic praise gives no decision help. Explain what makes the item distinctive, who it fits, and the experience to expect. Example: Describe Yuca Poppers through the crisp shell, soft savory center, bright guacamole, and easy-to-share fit.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Beyond &#039;It&#039;s Good&#039;</h2><p>Can you recommend a favorite without good, amazing, or delicious? Give a 20-second current-menu recommendation without generic praise or an ingredient dump.</p><h3>Success criteria</h3><ul><li>Truth and specificity</li><li>Description helps the decision</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one sensory detail and a point of view with a guest.</p><h3>Success criteria</h3><ul><li>Truth and specificity</li><li>Description helps the decision</li><li>Close with: Which description made a guest more confident?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 2: Sell Through Contrast</h2><p>Set expectations with accurate contrast. Truthful contrast makes style and fit understandable without insulting the item. Example: Hang 10 is bright, citrus-forward, and clean rather than a sugary frozen margarita.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Sell Through Contrast</h2><p>What becomes clearer when you explain what an item is not? Describe one food and one drink using a truthful contrast.</p><h3>Success criteria</h3><ul><li>Contrast stays positive</li><li>No false or stale claims</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one contrast statement in a real recommendation.</p><h3>Success criteria</h3><ul><li>Contrast stays positive</li><li>No false or stale claims</li><li>Close with: What expectation did contrast help set?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 3: Ask Before Recommending</h2><p>Earn the right to guide. One efficient preference question prevents menu dumping and makes the recommendation relevant. Example: Are you leaning bright and refreshing or smoky and spicy?</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Ask Before Recommending</h2><p>What is the smallest useful question you can ask? A guest gives a vague request; ask one question before choosing a direction.</p><h3>Success criteria</h3><ul><li>Question is efficient</li><li>Answer actually shapes the choice</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Ask a useful preference question before three recommendations.</p><h3>Success criteria</h3><ul><li>Question is efficient</li><li>Answer actually shapes the choice</li><li>Close with: Which question produced the best recommendation?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 4: Open the Experience</h2><p>Create curiosity before taking orders. A relevant opening direction helps the table picture the experience; it is not a memorized appetizer pitch. Example: For a first-time sharing table, explain street-taco size and offer one current shareable before mains.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Open the Experience</h2><p>How can an opening recommendation feel like care instead of an add-on? Create two natural openings for different guest profiles.</p><h3>Success criteria</h3><ul><li>No monologue</li><li>Direction fits the table</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one guided opening recommendation before taking the order.</p><h3>Success criteria</h3><ul><li>No monologue</li><li>Direction fits the table</li><li>Close with: Did the opening create curiosity or just add cost?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 5: Take a Position</h2><p>Reduce uncertainty with confidence. After learning the preference, choose a direction and explain why. Confidence should come from fit and current knowledge. Example: For what you described, I would choose the Jerk Shrimp Tacos.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Take a Position</h2><p>Why does &#039;either one is good&#039; fail the guest? Respond to two preferences with one recommendation and one reason.</p><h3>Success criteria</h3><ul><li>Recommendation fits</li><li>No promise that the guest must love it</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use &#039;For what you described...&#039; in one real interaction.</p><h3>Success criteria</h3><ul><li>Recommendation fits</li><li>No promise that the guest must love it</li><li>Close with: Where did taking a position make the decision easier?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 6: Texture Sells</h2><p>Make the bite understandable. Texture often gives more useful information than a list of ingredients. Example: Yuca Poppers: crisp outside, soft and savory in the center, with creamy guacamole and bright sauces.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Texture Sells</h2><p>Which texture word helps someone picture the food? Describe one current item through texture in one sentence.</p><h3>Success criteria</h3><ul><li>Sensory accuracy</li><li>Concise, current description</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one texture-led description with a guest.</p><h3>Success criteria</h3><ul><li>Sensory accuracy</li><li>Concise, current description</li><li>Close with: Which texture word helped a guest decide?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 7: Describe the Experience</h2><p>Sell the feeling, not the inventory. Translate the build into the way it eats or drinks: bright, filling, crisp, smoky, shareable, tropical, or refreshing. Example: The Zuma Beach Bowl eats fresh and filling at the same time, with vegetables, quinoa, and crunch.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Describe the Experience</h2><p>Can you describe an item without listing every ingredient? Describe one food without naming an ingredient.</p><h3>Success criteria</h3><ul><li>No empty adjectives</li><li>No overpromise</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Give one experience-led description.</p><h3>Success criteria</h3><ul><li>No empty adjectives</li><li>No overpromise</li><li>Close with: What experience did you help a guest picture?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 8: Pair With Purpose</h2><p>Explain why two choices work together. A pairing needs a reason connected to flavor, texture, heat, richness, or refreshment. Example: Pineapple Basil Smash adds herbal pineapple lift alongside Jerk Shrimp Tacos; Hang 10&#039;s lime and salt cut through Yuca Poppers.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Pair With Purpose</h2><p>What makes a pairing useful rather than automatic? Choose one verified food-and-drink pairing and explain the reason.</p><h3>Success criteria</h3><ul><li>Current, approved items only</li><li>Reason is specific and restrained</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Offer one reasoned pairing after learning the guest&#039;s preference.</p><h3>Success criteria</h3><ul><li>Current, approved items only</li><li>Reason is specific and restrained</li><li>Close with: Which pairing genuinely improved an order?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 9: When They Are Not Hungry</h2><p>Right-size the experience. Respect appetite while still helping. Recommend the right amount, not the largest amount. Example: If you want one thing in the middle, I would choose Yuca Poppers; if you want lighter, mix two tacos instead.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - When They Are Not Hungry</h2><p>How do we guide without pushing when appetite is small? Role-play &#039;We are not that hungry&#039; with one right-sized recommendation.</p><h3>Success criteria</h3><ul><li>Respects appetite</li><li>No oversized automatic recommendation</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Make one right-sized recommendation without pressure.</p><h3>Success criteria</h3><ul><li>Respects appetite</li><li>No oversized automatic recommendation</li><li>Close with: Did we respect appetite while still being useful?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 10: Twenty-Second Challenge</h2><p>Combine the full formula. Use Observe, Ask, Interpret, Recommend, Describe naturally and efficiently. Example: You said bright and not sweet, so I would go Hang 10. It is citrus-forward, clean, and the salt rim keeps it lively.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Twenty-Second Challenge</h2><p>Can you learn, recommend, and describe in twenty seconds? Deliver a 20-second recommendation for a surprise guest profile.</p><h3>Success criteria</h3><ul><li>Preference learned</li><li>Current facts</li><li>Clear point of view</li><li>Human pace</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Deliver your cleanest complete recommendation of the cycle.</p><h3>Success criteria</h3><ul><li>Preference learned</li><li>Current facts</li><li>Clear point of view</li><li>Human pace</li><li>Close with: Which part of the formula now feels natural?</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>short-answer</strong>: Name the behavior that changed, the floor evidence, and the behavior that still needs another cycle.</li><li><strong>practical</strong>: Deliver one surprise day from the cycle and show how it will be observed and reinforced during service.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 50, true, true, 20, ARRAY['daily-mastermind', 'cycle-2', 'leadership', 'floor-training', 'practical-required']::text[]),
  ('cur-mastermind-last-recovery', 'sec-daily-masterminds', 'Cycle 3 - L.A.S.T. Recovery', 'Guest recovery and system learning. Ten shifts, one five-minute behavior rep per shift.', 'mastermind-last-recovery', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-mastermind-last-recovery"><header><p class="curriculum-eyebrow">daily-mastermind / cycle-3 / leadership / floor-training</p><h1>Cycle 3 - L.A.S.T. Recovery</h1><p>Guest recovery and system learning. Ten shifts, one five-minute behavior rep per shift.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Run all ten pre-shift sessions in sequence.</li><li>Observe and coach each day&#039;s behavior during live service.</li><li>Repeat a day when behavior has not transferred to the floor.</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Cycle standard</h2><p>Care for the guest first, own the problem through follow-up, then improve the system behind the miss.</p></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 1: Listen Without Interrupting</h2><p>Hear the concern beneath the complaint. Do not prepare a defense while the guest talks. Listen for impact, emotion, expectation, and the outcome they need. Example: A complaint about a long wait may also be about feeling forgotten and unable to plan.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Listen Without Interrupting</h2><p>What does the guest care about beyond the first sentence? One person speaks for 30 seconds; the listener summarizes without rebuttal.</p><h3>Success criteria</h3><ul><li>No interruption</li><li>Summary captures more than the literal words</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Summarize the concern before proposing a solution.</p><h3>Success criteria</h3><ul><li>No interruption</li><li>Summary captures more than the literal words</li><li>Close with: What did the guest actually care about?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 2: Apologize Without Excuses</h2><p>Acknowledge before explaining. Apologize for the experience and accept responsibility to care for it; context can wait. Example: You should not have waited that long without an update. I am getting one now.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Apologize Without Excuses</h2><p>What makes an apology lower the temperature? Rewrite three excuse-first apologies into direct acknowledgment.</p><h3>Success criteria</h3><ul><li>No &#039;but&#039;</li><li>Acknowledgment is specific</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Give any necessary apology before explanation.</p><h3>Success criteria</h3><ul><li>No &#039;but&#039;</li><li>Acknowledgment is specific</li><li>Close with: Did the apology lower the temperature?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 3: Replace &#039;But&#039;</h2><p>Stay on the guest&#039;s team. But often cancels ownership. Replace it with what you can do, what you will verify, and when you will return. Example: Instead of &#039;I am sorry, but that is policy,&#039; say &#039;Here is what I can do; let me confirm the next step.&#039;</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Replace &#039;But&#039;</h2><p>What word quietly turns an apology into a debate? Rapid-fire replace five recovery &#039;buts&#039;.</p><h3>Success criteria</h3><ul><li>No blame or policy shield</li><li>Action remains honest</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Catch and replace every recovery &#039;but&#039;.</p><h3>Success criteria</h3><ul><li>No blame or policy shield</li><li>Action remains honest</li><li>Close with: Which phrase kept us on the same team?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 4: Own the Problem</h2><p>Walk it to the solution. If a problem reaches you, own it until solved or physically and verbally transferred to a named person who accepts it. Example: Do not point toward a server; introduce the owner, state the request, receive confirmation, and follow up.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Own the Problem</h2><p>When is a handoff actually complete? Practice a warm transfer for three common requests.</p><h3>Success criteria</h3><ul><li>Named owner</li><li>Confirmation and follow-up</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Walk every problem to a person or solution.</p><h3>Success criteria</h3><ul><li>Named owner</li><li>Confirmation and follow-up</li><li>Close with: Which problem stayed yours until the guest felt closure?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 5: Ticket-Time Recovery</h2><p>Update before frustration spikes. Find aging tickets early, give an accurate update, and keep the table cared for while the item moves. Example: You have waited longer than you should have. I am checking the exact status and will return in two minutes.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Ticket-Time Recovery</h2><p>When should a guest hear about a delay? Role-play a 30-minute delay with two proactive updates.</p><h3>Success criteria</h3><ul><li>Accuracy and timing</li><li>No vague promises</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Find one aging ticket early and update before being chased.</p><h3>Success criteria</h3><ul><li>Accuracy and timing</li><li>No vague promises</li><li>Close with: Where did an update prevent frustration?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 6: Incorrect Entrée</h2><p>Repair the whole table experience. Own the missed item, protect food safety, involve the MOD, and care for the rest of the table while the correction moves. Example: Acknowledge the error, remove or manage the item appropriately, set a realistic update, and follow up with everyone affected.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Incorrect Entrée</h2><p>Who needs care when one plate is wrong? Run a wrong-item recovery with one guest waiting while others have food.</p><h3>Success criteria</h3><ul><li>No blame</li><li>Rest of table is not forgotten</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Manage both the correction and the table&#039;s pace.</p><h3>Success criteria</h3><ul><li>No blame</li><li>Rest of table is not forgotten</li><li>Close with: Did we repair the table, not only the plate?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 7: They Simply Do Not Like It</h2><p>Separate preference from preparation. Do not debate taste. Ask what missed - sweetness, spice, texture, or style - then guide the replacement from the answer. Example: I am sorry this is not landing for you. Is it the sweetness, spice, or overall style?</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - They Simply Do Not Like It</h2><p>Can a correctly made item still be wrong for this guest? Recover without insulting the dish or making the guest wrong.</p><h3>Success criteria</h3><ul><li>No defensiveness</li><li>Replacement fits new information</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Ask one preference question before a replacement recommendation.</p><h3>Success criteria</h3><ul><li>No defensiveness</li><li>Replacement fits new information</li><li>Close with: Was the issue preparation, expectation, or preference?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 8: The Recovery Follow-Up</h2><p>Verify the emotion, not only the transaction. Operational action does not prove trust is repaired. Return personally and ask whether the solution actually worked. Example: I wanted to come back personally and make sure the replacement is right and that we have truly taken care of this.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - The Recovery Follow-Up</h2><p>Why is removing an item from the check not the end? Practice a ten-second follow-up specific to the original concern.</p><h3>Success criteria</h3><ul><li>Specific, personal follow-up</li><li>Arrives in time to fix another miss</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Follow up on every recovery before departure.</p><h3>Success criteria</h3><ul><li>Specific, personal follow-up</li><li>Arrives in time to fix another miss</li><li>Close with: Which follow-up proved whether recovery worked?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 9: Think Beyond the Complaint</h2><p>Find the system behind the miss. After care is restored, capture the standard, owner, trigger, method, verification, and recovery that failed. Example: A missed allergy communication requires a full system review, not a reminder to one person.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Think Beyond the Complaint</h2><p>If this happened tomorrow, what would we wish we changed tonight? Run the six-part System Test on a recent complaint.</p><h3>Success criteria</h3><ul><li>Root cause is specific</li><li>Action is more than &#039;remind everyone&#039;</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Record one system lesson from a recovery.</p><h3>Success criteria</h3><ul><li>Root cause is specific</li><li>Action is more than &#039;remind everyone&#039;</li><li>Close with: What will change so tomorrow&#039;s team is less likely to repeat it?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 10: Full L.A.S.T. Certification</h2><p>Combine care and learning. The structure lives in the teammate&#039;s thinking while the language stays natural: Listen, Apologize, Solve, Think. Example: Complete the full model without announcing the acronym&#039;s letters.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Full L.A.S.T. Certification</h2><p>Can we stay calm, human, and decisive from first sentence through follow-up? Run a surprise 90-second scenario and explain the Think step.</p><h3>Success criteria</h3><ul><li>Listening</li><li>Acknowledgment</li><li>Ownership</li><li>Follow-up</li><li>System thinking</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use the full model on any real recovery and log evidence.</p><h3>Success criteria</h3><ul><li>Listening</li><li>Acknowledgment</li><li>Ownership</li><li>Follow-up</li><li>System thinking</li><li>Close with: Which L.A.S.T. step needs another cycle?</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>short-answer</strong>: Name the behavior that changed, the floor evidence, and the behavior that still needs another cycle.</li><li><strong>practical</strong>: Deliver one surprise day from the cycle and show how it will be observed and reinforced during service.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 50, true, true, 30, ARRAY['daily-mastermind', 'cycle-3', 'leadership', 'floor-training', 'practical-required']::text[]),
  ('cur-mastermind-accountability-without-ego', 'sec-daily-masterminds', 'Cycle 4 - Accountability Without Ego', 'Direct feedback that protects people and standards. Ten shifts, one five-minute behavior rep per shift.', 'mastermind-accountability-without-ego', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-mastermind-accountability-without-ego"><header><p class="curriculum-eyebrow">daily-mastermind / cycle-4 / leadership / floor-training</p><h1>Cycle 4 - Accountability Without Ego</h1><p>Direct feedback that protects people and standards. Ten shifts, one five-minute behavior rep per shift.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Run all ten pre-shift sessions in sequence.</li><li>Observe and coach each day&#039;s behavior during live service.</li><li>Repeat a day when behavior has not transferred to the floor.</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Cycle standard</h2><p>Coach observable behavior, receive with Heard, create the next rep, and verify the reset without humiliation or theater.</p></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 1: Feedback Is Not Disrespect</h2><p>Separate correction from attack. Discomfort is not disrespect. Healthy accountability names behavior, connects it to a shared standard, and requests a reset. Example: &#039;Your station has been below standard twice&#039; is coachable; &#039;You are lazy&#039; attacks identity.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Feedback Is Not Disrespect</h2><p>Why can respectful correction still feel uncomfortable? Convert two labels into neutral observations and clear actions.</p><h3>Success criteria</h3><ul><li>Tone, privacy, specificity</li><li>Employee knows what to change</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Give one timely behavioral correction without apology or aggression.</p><h3>Success criteria</h3><ul><li>Tone, privacy, specificity</li><li>Employee knows what to change</li><li>Close with: Did feedback protect the standard and dignity?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 2: The &#039;Heard&#039; Response</h2><p>Receive before explaining. Heard signals the standard and action were received. Fix first; give operationally useful context after the reset. Example: Heard. Fixed. Can you show me what you want next time so I hit it consistently?</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - The &#039;Heard&#039; Response</h2><p>What becomes possible when the first response is Heard? Receive, fix, then ask one useful clarification without defense.</p><h3>Success criteria</h3><ul><li>No counter-accusation or résumé speech</li><li>Clarification serves execution</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use Heard as the first response to every valid correction.</p><h3>Success criteria</h3><ul><li>No counter-accusation or résumé speech</li><li>Clarification serves execution</li><li>Close with: Where did clean receiving save time or tension?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 3: 10 for 10</h2><p>Reset drift before it compounds. 10 for 10 is a neutral, roughly 30-second return to standard. Anyone can call it; leaders participate and verify. Example: 10 for 10, bar. Glassware home, trash clear, garnish full - beautiful, that is our standard.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - 10 for 10</h2><p>What small disorder could become the next bottleneck? Create three station misses and complete the reset without blame.</p><h3>Success criteria</h3><ul><li>Timely, shared, complete</li><li>Released without lingering emotion</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use one appropriate reset only if the room actually drifts.</p><h3>Success criteria</h3><ul><li>Timely, shared, complete</li><li>Released without lingering emotion</li><li>Close with: Did the reset protect the next hour?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 4: Keep / Start / Stop</h2><p>Make coaching balanced and actionable. Keep reinforces behavior worth repeating; Start names a missing action; Stop names behavior creating friction. Never invent praise. Example: Keep your table energy. Start checking the pass. Stop walking past food because it is not yours.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Keep / Start / Stop</h2><p>What should continue, begin, and end? Give a 30-second Keep / Start / Stop for a food-running miss.</p><h3>Success criteria</h3><ul><li>Behavior, not personality</li><li>One clear action per category</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use the framework once and confirm the reset.</p><h3>Success criteria</h3><ul><li>Behavior, not personality</li><li>One clear action per category</li><li>Close with: What is now easier to repeat or change?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 5: Behavior, Not Identity</h2><p>Remove labels from coaching. Coach what can be observed and changed. Identity labels create shame and argument; behavior creates a path forward. Example: You argued before acknowledging two corrections is usable; your attitude sucks is not.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Behavior, Not Identity</h2><p>Can a person act carelessly without being a careless person? Rewrite five labels as observation, standard, and next action.</p><h3>Success criteria</h3><ul><li>No always, never, lazy, careless</li><li>Evidence is quotable</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Catch every personality label before it leaves your mouth.</p><h3>Success criteria</h3><ul><li>No always, never, lazy, careless</li><li>Evidence is quotable</li><li>Close with: What exact behavior needs to change?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 6: Challenge Up Respectfully</h2><p>Protect the standard across titles. Challenge upward with timely facts, appropriate privacy, and the shared outcome. Leaders reward the courage they request. Example: I may be missing context, but the allergy item moved without verification. Can we pause and confirm?</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Challenge Up Respectfully</h2><p>How can someone challenge a leader without a power contest? Team member challenges a manager; manager receives with Heard. Thank you.</p><h3>Success criteria</h3><ul><li>Safety, facts, timing, tone</li><li>No retaliation or dismissal</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Raise one legitimate concern directly to the correct person.</p><h3>Success criteria</h3><ul><li>Safety, facts, timing, tone</li><li>No retaliation or dismissal</li><li>Close with: How did leadership respond when the standard moved upward?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 7: Coach a Peer</h2><p>Share ownership without acting like a boss. Peer accountability is brief, factual, and anchored in the shared standard. Transfer formal issues rather than escalating conflict. Example: We have food sitting and both of us are clear. Can you grab 31 while I take 28?</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Coach a Peer</h2><p>What makes peer coaching helpful instead of controlling? Practice one peer reset and one escalation after refusal.</p><h3>Success criteria</h3><ul><li>No bossy tone or embarrassment</li><li>Formal conflict transfers appropriately</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Protect one standard with clean peer language.</p><h3>Success criteria</h3><ul><li>No bossy tone or embarrassment</li><li>Formal conflict transfers appropriately</li><li>Close with: Where did peer accountability help without drama?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 8: Receive Feedback From Anyone</h2><p>Let the best information win. Titles do not create immunity. Thank the person, check the standard, correct, and follow up. Example: A new host catches an expired restroom check; the manager says Heard, fixes it, and recognizes the catch.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Receive Feedback From Anyone</h2><p>What does a junior employee learn when a leader gets defensive? The junior person gives a correction; the leader practices receiving and acting.</p><h3>Success criteria</h3><ul><li>No power signals or dismissal</li><li>Behavior actually changes</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Invite one piece of upward feedback and do not explain first.</p><h3>Success criteria</h3><ul><li>No power signals or dismissal</li><li>Behavior actually changes</li><li>Close with: What did someone see that leadership needed to hear?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 9: Correct Without Embarrassment</h2><p>Choose the right audience and moment. Correct risk immediately; protect dignity. A short public safety cue may be necessary, while deeper coaching usually belongs in private. Example: At the pass: Allergy hold - verify now. In private later: observation, standard, risk, and next rep.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Correct Without Embarrassment</h2><p>When should correction be public, and when private? Sort five scenarios into immediate cue, private coach, or formal follow-up.</p><h3>Success criteria</h3><ul><li>No sarcasm or public lecture</li><li>Safety corrections are not delayed</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Use the smallest audience that can safely correct the issue.</p><h3>Success criteria</h3><ul><li>No sarcasm or public lecture</li><li>Safety corrections are not delayed</li><li>Close with: Did correction preserve the standard and ability to recover?</li></ul></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Day 10: Accountability Reflection</h2><p>Make clean feedback cultural. No-ego culture means feedback travels quickly in every direction and people recover fast. Vocabulary alone is not proof. Example: Keep clean resets. Start recognizing people who receive well. Stop debating before fixing.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-minute drill - Accountability Reflection</h2><p>What accountability behavior should this team keep, start, and stop? Complete a team Keep / Start / Stop about feedback.</p><h3>Success criteria</h3><ul><li>Standards protected</li><li>Fear or ego still slowing action</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Today&#039;s floor challenge</h2><p>Demonstrate the cleanest receive-and-reset behavior of the cycle.</p><h3>Success criteria</h3><ul><li>Standards protected</li><li>Fear or ego still slowing action</li><li>Close with: What will prove two weeks from now that accountability changed?</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>short-answer</strong>: Name the behavior that changed, the floor evidence, and the behavior that still needs another cycle.</li><li><strong>practical</strong>: Deliver one surprise day from the cycle and show how it will be observed and reinforced during service.</li></ol></section><footer><small>Sources: leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 50, true, true, 40, ARRAY['daily-mastermind', 'cycle-4', 'leadership', 'floor-training', 'practical-required']::text[]),
  ('cur-trainer-identity-selection', 'sec-trainer-operating-system', 'Trainer Identity, Selection + Contract', 'Select culture carriers through evidence, not tenure, speed, popularity, or schedule convenience.', 'trainer-identity-selection', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-identity-selection"><header><p class="curriculum-eyebrow">trainer-os / selection / required</p><h1>Trainer Identity, Selection + Contract</h1><p>Select culture carriers through evidence, not tenure, speed, popularity, or schedule convenience.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Explain the trainer mission and role boundaries</li><li>Apply the evidence-based selection standard</li><li>Commit to source discipline and honest sign-offs</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Trainer mission</h2><p>We do not hand people information. We build capability. Training is hospitality before the guest ever arrives.</p></section><section class="curriculum-block curriculum-checklist"><h2>Who earns the responsibility</h2><ul><li>Role competence under normal volume and pressure</li><li>Culture and hospitality</li><li>Consistency</li><li>Clear communication</li><li>Patience without lowered standards</li><li>Behavioral accountability</li><li>Reliability and source discipline</li></ul></section><section class="curriculum-block curriculum-comparison"><h2>Trainer vs. leadership</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Certified trainer owns</th><th>Leadership owns</th></tr></thead><tbody><tr><td>Prepare the objective and current source</td><td>Selection, schedules, materials, bandwidth, and system health</td></tr><tr><td>Demonstrate, create reps, coach, and document evidence</td><td>Policy, discipline, accommodations, employment decisions, and final certification authority</td></tr><tr><td>Build independence</td><td>Protect enough training bandwidth and resolve source conflicts</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>The contract</h2><p>Never teach a hidden shortcut, never invent an answer, never sign off exposure as competency, and never use friendship, comfort, speed, or schedule convenience to certify unproven work.</p></section><section class="curriculum-block curriculum-practice"><h2>Trainer audition</h2><p>Teach one five-minute current role skill, respond to a planned miss, and complete a short evidence note.</p><h3>Success criteria</h3><ul><li>Current approved source</li><li>Explains why</li><li>Creates a rep</li><li>Coaches behavior</li><li>No shortcut or guess</li><li>Evidence is specific</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: What qualifies a person to train independently?</li><li><strong>practical</strong>: Complete the five-minute trainer audition.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 55, true, true, 10, ARRAY['trainer-os', 'selection', 'required', 'practical-required']::text[]),
  ('cur-trainer-seven-step-method', 'sec-trainer-operating-system', 'The Seven-Step Training Method', 'Explain it. Show it. Rehearse it. Use it. Coach it. Prove it. Recheck it.', 'seven-step-training-method', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-seven-step-method"><header><p class="curriculum-eyebrow">trainer-os / method / required</p><h1>The Seven-Step Training Method</h1><p>Explain it. Show it. Rehearse it. Use it. Coach it. Prove it. Recheck it.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use Teach &gt; Demonstrate &gt; Rehearse &gt; Run Live &gt; Coach &gt; Certify &gt; Audit</li><li>Make critical decisions visible</li><li>Separate attendance from evidence</li></ul></section><section class="curriculum-block curriculum-steps"><h2>The method</h2><ol><li>Teach: explain the purpose, observable standard, approved source, steps, decisions, and stop points.</li><li>Demonstrate: perform at normal speed, repeat with slow decision narration, then perform at normal speed again.</li><li>Rehearse: create controlled reps away from guest risk; coach one priority and rerun immediately.</li><li>Run Live: name the independence level and intervention boundary before the rep.</li><li>Coach: use observation, standard, impact, reset, confirmation, and second-take evidence.</li><li>Certify: require knowledge, independent performance, and consistency; trainers also require transfer proof.</li><li>Audit: recheck on another shift, under pressure, and ideally with another qualified observer.</li></ol></section><section class="curriculum-block curriculum-comparison"><h2>Demonstration passes</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Pass</th><th>Learner action</th></tr></thead><tbody><tr><td>Normal speed</td><td>Watch the complete flow and identify what stands out</td></tr><tr><td>Slow narration</td><td>Ask questions and name decisions/checkpoints</td></tr><tr><td>Normal speed again</td><td>Predict the next decision while the trainer works at service pace</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-practice"><h2>Make thinking visible</h2><p>Teach a current role standard using all seven steps; add one changed condition after the base rep is stable.</p><h3>Success criteria</h3><ul><li>Objective is narrow</li><li>Source is current</li><li>Decisions are narrated</li><li>Learner completes reps</li><li>Live boundary is explicit</li><li>Evidence and audit are recorded</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: What comes after a coached miss?</li><li><strong>practical</strong>: Run the full seven-step loop on an approved task.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 70, true, true, 20, ARRAY['trainer-os', 'method', 'required', 'practical-required']::text[]),
  ('cur-trainer-shift-autonomy', 'sec-trainer-operating-system', 'Training Shifts + the Independence Ladder', 'Schedule training as development, not disguised labor, and transfer ownership in safe stages.', 'training-shift-autonomy', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-shift-autonomy"><header><p class="curriculum-eyebrow">trainer-os / shift-plan / autonomy / required</p><h1>Training Shifts + the Independence Ladder</h1><p>Schedule training as development, not disguised labor, and transfer ownership in safe stages.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Plan one priority behavior for the shift</li><li>Assign a safe independence level</li><li>Hand off evidence and the next exact rep</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-warning"><h2>Manager protection rule</h2><p>Do not assign a trainer a normal full workload and expect a complete learning experience on top of it. Schedule the responsibility, name the objective, and protect enough bandwidth to observe.</p></section><section class="curriculum-block curriculum-steps"><h2>Independence ladder</h2><ol><li>Introduced - learner has seen and discussed the standard</li><li>Rehearsed - controlled reps completed with coaching</li><li>Live with direction - trainer provides active cues</li><li>Live with check - learner acts, trainer verifies checkpoints</li><li>Independent certification rep - no coaching unless safety requires intervention</li><li>Certified - evidence meets the role standard</li><li>Audited - behavior survives another shift and observer</li></ol></section><section class="curriculum-block curriculum-checklist"><h2>Every training shift</h2><ul><li>Review prior evidence</li><li>Name one priority objective</li><li>Confirm current source and materials</li><li>State ownership and stop points</li><li>Create base rep, second take, and variation</li><li>Use Keep / Start / Stop</li><li>Document status, evidence, risk, exact next rep, and manager handoff</li></ul></section><section class="curriculum-block curriculum-scenario"><h2>Volume narrows; it does not erase</h2><p>Volume hits in the middle of a training rep. Safely narrow the trainee&#039;s ownership without abandoning the standard or turning them into untrained labor.</p><h3>Success criteria</h3><ul><li>One task remains owned</li><li>Trainer protects the rest</li><li>Safety boundaries stay explicit</li><li>Decisions are debriefed after the push</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>true-false</strong>: A training calendar date is enough reason to certify a skill.</li><li><strong>practical</strong>: Plan and lead a training block through a realistic volume spike.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 45, true, true, 30, ARRAY['trainer-os', 'shift-plan', 'autonomy', 'required', 'practical-required']::text[]),
  ('cur-trainer-coaching-learning', 'sec-trainer-operating-system', 'Coach the Rep, Protect the Person', 'Use precise evidence, productive struggle, 80/20 questions, and immediate second takes.', 'coach-the-rep', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-coaching-learning"><header><p class="curriculum-eyebrow">trainer-os / coaching / learning / required</p><h1>Coach the Rep, Protect the Person</h1><p>Use precise evidence, productive struggle, 80/20 questions, and immediate second takes.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use the 60-Second Coach</li><li>Diagnose clarity, skill, system, environment, or willingness</li><li>Keep questions and honest uncertainty safe</li></ul></section><section class="curriculum-block curriculum-steps"><h2>The 60-Second Coach</h2><ol><li>Observation - quote behavior, words, timing, or result</li><li>Standard - point to the approved source</li><li>Impact - connect to guest, team, safety, accuracy, pace, or trust</li><li>Reset - give one change for the next rep</li><li>Confirm - learner states the change and reruns</li></ol></section><section class="curriculum-block curriculum-script"><h2>Difficult moments</h2><blockquote><p>Overwhelmed: &#039;Tell me the one thing you are trying to control. We will get one clean rep, then add the next piece.&#039;</p><p>Defensive: &#039;I am coaching the behavior I observed. Tell me what you heard the standard to be, then we will rerun.&#039;</p><p>Conflicting instructions: &#039;We are not making you choose between trainers. We will verify the current written standard.&#039;</p><p>Trainer unsure: &#039;I do not want to teach a guess. I will verify and show you where the approved source lives.&#039;</p><p>Repeat miss: &#039;Show me where your process breaks; then we will diagnose clarity, skill, environment, or willingness.&#039;</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Second-take lab</h2><p>Observe a planned miss, quote facts only, give one reset, and rerun without a speech between reps.</p><h3>Success criteria</h3><ul><li>No identity labels</li><li>One observable change</li><li>Dignity and urgency protected</li><li>Second take proves whether coaching worked</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: What proves a coaching conversation worked?</li><li><strong>practical</strong>: Coach an overwhelmed trainee, a defensive trainee, and a source conflict.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 60, true, true, 40, ARRAY['trainer-os', 'coaching', 'learning', 'required', 'practical-required']::text[]),
  ('cur-trainer-four-labs', 'sec-trainer-operating-system', 'Two-Week Trainer Development Sprint', 'Complete four leadership-run labs, progressive co-training, and floor evidence before the practical.', 'trainer-development-sprint', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-four-labs"><header><p class="curriculum-eyebrow">trainer-os / labs / co-training / required</p><h1>Two-Week Trainer Development Sprint</h1><p>Complete four leadership-run labs, progressive co-training, and floor evidence before the practical.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Complete all four 75-minute labs</li><li>Advance through controlled co-training milestones</li><li>Demonstrate transfer under observation</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Four labs</h2><ol><li>Lab 1 - What Trainers Teach Without Speaking: identity, operating beliefs, boundaries, contract, and training hospitality.</li><li>Lab 2 - Make the Standard Visible: Teach, Demonstrate, Rehearse, and Run Live.</li><li>Lab 3 - Coach the Rep, Protect the Person: evidence, 60-Second Coach, 80/20, difficult moments, and second takes.</li><li>Lab 4 - Certify, Audit, Improve: honest decisions, documentation, audit, and module repair.</li></ol></section><section class="curriculum-block curriculum-steps"><h2>Co-training path</h2><ol><li>Observe a full training shift</li><li>Own one Teach &gt; Demonstrate &gt; Rehearse module</li><li>Own one live block and evidence note</li><li>Lead a full training shift under observation</li><li>Complete the final practical</li></ol></section><section class="curriculum-block curriculum-callout curriculum-tone-sand"><h2>Do not rush the ladder</h2><p>A candidate may repeat a milestone. Repetition is not failure; unearned authority is. Advance only when evidence supports the next level.</p></section><section class="curriculum-block curriculum-field-assignment"><h2>Sprint proof</h2><p>Complete all four lab assignments and four co-training milestones in the recommended two-week sequence.</p><h3>Success criteria</h3><ul><li>Every candidate performs</li><li>Floor evidence is specific</li><li>No observation-only certification</li><li>Qualified observer approves each advancement</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>short-answer</strong>: Explain the purpose and evidence for each of the four labs.</li><li><strong>practical</strong>: Complete the four co-training milestones with observer records.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 300, true, true, 50, ARRAY['trainer-os', 'labs', 'co-training', 'required', 'practical-required']::text[]),
  ('cur-trainer-certification-audit', 'sec-trainer-operating-system', 'Certification, Audit + Calibration', 'Protect the meaning of trained with knowledge, performance, consistency, transfer, and ongoing recalibration.', 'certification-audit-calibration', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-certification-audit"><header><p class="curriculum-eyebrow">trainer-os / certification / audit / required</p><h1>Certification, Audit + Calibration</h1><p>Protect the meaning of trained with knowledge, performance, consistency, transfer, and ongoing recalibration.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Make an evidence-backed certification decision</li><li>Identify critical misses</li><li>Keep trainer status active through audit and calibration</li></ul></section><section class="curriculum-block curriculum-comparison"><h2>Proofs</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Proof</th><th>Meaning</th></tr></thead><tbody><tr><td>Knowledge</td><td>Explains why, standard, steps, boundaries, and escalation without reading</td></tr><tr><td>Performance</td><td>Executes accurately under realistic conditions without the trainer carrying the result</td></tr><tr><td>Consistency</td><td>Behavior survives another shift and pressure</td></tr><tr><td>Transfer - trainer only</td><td>Builds the same capability in another person using the full method</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-checklist"><h2>Certification lifecycle</h2><ul><li>Pass audition and eligibility</li><li>Complete four labs and floor evidence</li><li>Complete co-training milestones</li><li>Pass final practical at 42/50 or better with no area below 3</li><li>Zero critical safety, accuracy, hospitality, responsible-service, or integrity miss</li><li>Complete 14- and 30-day provisional observations</li><li>Quarterly observed block/calibration</li><li>Annual recertification or equivalent practical</li><li>Re-certify after material changes</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-warning"><h2>Pause triggers</h2><p>Critical miss, dishonest sign-off, repeated drift, culture damage, refusal to calibrate, or inactive status pauses training authority until leadership records the evidence, owner, development step, and review date.</p></section><section class="curriculum-block curriculum-practice"><h2>Borderline decision</h2><p>Score a mixed performance, compare observers, and defend certify, continue practice, retrain, manager review, or pause using evidence.</p><h3>Success criteria</h3><ul><li>Independent scores first</li><li>Quotes evidence</li><li>Critical gates applied</li><li>Next step and audit owner recorded</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which proof is unique to trainer certification?</li><li><strong>practical</strong>: Make and document a borderline certification decision, then plan its audit.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 55, true, true, 60, ARRAY['trainer-os', 'certification', 'audit', 'required', 'practical-required']::text[]),
  ('cur-trainer-final-practical', 'sec-trainer-operating-system', 'Trainer Final Practical', 'Prove you can build capability from plan through audit without ego, shortcuts, or dependence.', 'trainer-final-practical', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-trainer-final-practical"><header><p class="curriculum-eyebrow">trainer-os / final-practical / certification / required</p><h1>Trainer Final Practical</h1><p>Prove you can build capability from plan through audit without ego, shortcuts, or dependence.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Plan and deliver a complete training module</li><li>Coach a planned miss and changed condition</li><li>Make an honest certification decision and audit plan</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Practical conditions</h2><ul><li>Submit one-page plan one day before</li><li>Use an assigned current standard</li><li>Teach why and standard in under three minutes</li><li>Demonstrate normal / slow / normal</li><li>Create two reps, one coached miss, and one variation</li><li>Set a safe live/pressure boundary</li><li>Use self-assessment and Keep / Start / Stop</li><li>Choose status, document proof, and plan the audit</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Scoring gate</h2><p>Passing requires 42/50 or better, no area below 3, and zero critical safety, accuracy, hospitality, responsible-service, or integrity miss.</p></section><section class="curriculum-block curriculum-field-assignment"><h2>Transfer proof</h2><p>A qualified observer evaluates the candidate on what the learner can now understand and do, not on how impressive the trainer sounds.</p><h3>Success criteria</h3><ul><li>Plan</li><li>Teach</li><li>Demonstrate</li><li>Rehearse</li><li>Run live/simulate</li><li>Coach/debrief</li><li>Certify/document</li><li>Audit</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 84%; practical required.</p><ol><li><strong>short-answer</strong>: Submit the one-page training plan and approved source.</li><li><strong>practical</strong>: Complete the Trainer Final Practical.</li></ol></section><footer><small>Sources: trainer-os-1, leadership-os-1, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 90, true, true, 70, ARRAY['trainer-os', 'final-practical', 'certification', 'required', 'practical-required']::text[]),
  ('cur-server-identity-readiness', 'sec-server-onboarding', 'Server Identity + Shift Readiness', 'Own the table''s full experience from welcome through farewell while protecting the whole room.', 'server-identity-readiness', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-identity-readiness"><header><p class="curriculum-eyebrow">server / onboarding / required</p><h1>Server Identity + Shift Readiness</h1><p>Own the table&#039;s full experience from welcome through farewell while protecting the whole room.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Explain the server mission</li><li>Arrive guest-ready</li><li>Use CARE and five-foot ownership</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Role mission</h2><p>Read the guest, guide decisions, pace the meal, communicate clearly, remove friction, and finish strong.</p></section><section class="curriculum-block curriculum-checklist"><h2>Ready to work</h2><ul><li>On time and in uniform</li><li>Coffee, food, and personal tasks handled</li><li>Phone away</li><li>Current 7shifts updates read</li><li>Menu, specials, 86s, and station reviewed</li><li>Tools and sidework ready</li></ul></section><section class="curriculum-block curriculum-practice"><h2>Five-foot scan</h2><p>Scan a staged section and choose the next three useful actions.</p><h3>Success criteria</h3><ul><li>Guest priority first</li><li>Food and safety protected</li><li>Named handoff when needed</li><li>No low-priority busywork</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the server&#039;s highest responsibility?</li><li><strong>practical</strong>: Complete a readiness check and five-foot scan.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 25, true, true, 10, ARRAY['server', 'onboarding', 'required', 'practical-required']::text[]),
  ('cur-server-guest-journey', 'sec-server-onboarding', 'The Ditch Guest Journey', 'Make every handoff from acknowledgment to goodbye observable, paced, and personal.', 'server-guest-journey', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-guest-journey"><header><p class="curriculum-eyebrow">server / guest-journey / required</p><h1>The Ditch Guest Journey</h1><p>Make every handoff from acknowledgment to goodbye observable, paced, and personal.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Execute the full service sequence</li><li>Use specific check-backs</li><li>Close every handoff</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Service sequence</h2><ol><li>Acknowledge immediately; full greet as soon as guest care allows</li><li>Discover first visit, occasion, appetite, pace, and guidance preference</li><li>Guide beverage and food decisions</li><li>Enter accurately and communicate timing/modifiers</li><li>Course and pace with support handoffs</li><li>Check back specifically while a correction is possible</li><li>Clear and offer the next relevant moment</li><li>Process payment promptly</li><li>Thank and give a real reason to return</li></ol></section><section class="curriculum-block curriculum-comparison"><h2>Specific check-backs</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Avoid</th><th>Use</th></tr></thead><tbody><tr><td>Everything good?</td><td>How is the spice level on the Jerk Shrimp Tacos?</td></tr><tr><td>All set?</td><td>Is the replacement temperature where it should be now?</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-practice"><h2>Three table styles</h2><p>Run the sequence for a quiet pair, a first-time family, and a time-limited group.</p><h3>Success criteria</h3><ul><li>Baseline consistent</li><li>Pace adapts</li><li>No scripted monologue</li><li>Handoffs confirmed</li><li>Strong close</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: When should a delay be communicated?</li><li><strong>practical</strong>: Run one complete table role-play from arrival through farewell.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 35, true, true, 20, ARRAY['server', 'guest-journey', 'required', 'practical-required']::text[]),
  ('cur-server-food-menu', 'sec-server-onboarding', 'Current Food Menu Fluency', 'Learn the current printed menu by category, fit, flavor, portion expectation, and approved source - never by stale script.', 'server-food-menu', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-food-menu"><header><p class="curriculum-eyebrow">server / menu / food / required</p><h1>Current Food Menu Fluency</h1><p>Learn the current printed menu by category, fit, flavor, portion expectation, and approved source - never by stale script.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Locate and describe every current printed food item</li><li>Set honest size and portion expectations</li><li>Verify rather than infer allergy answers</li></ul></section><section class="curriculum-block curriculum-menu-reference"><h2>Current dining menu</h2><p>Learn guest-facing name, category, description, printed price, and approved add-ons. Live POS controls current price and availability.</p><ul><li><strong>Chips + Guac</strong> <span>$12</span><p>Mashed avocado, fresh lime juice, onion, tomato, cilantro, and pickled jalapeños with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Yuca Poppers</strong> <span>$14</span><p>Fried yuca croquettes with guacamole, sweet chili, herb aioli, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Empanada del Día</strong> <span>$14</span><p>The daily empanada served with herb aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Longboard Mozz Sticks</strong> <span>$10</span><p>House-made panko-breaded mozzarella with marinara.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Queso Blanco</strong> <span>$11</span><p>Queso with charred poblano and jalapeño peppers, served with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Carnitas Nachos</strong> <span>$18</span><p>Corn tortilla chips, queso blanco, pico de gallo, shredded lettuce, lime crema, and pickled jalapeños.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Crispy Calamari</strong> <span>$20</span><p>Topped with toasted coconut and scallions; served with sweet Thai chili sauce.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Fried Pickles</strong> <span>$8</span><p>House-made beer-battered pickle chips with horseradish aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Tuna Tartare</strong> <span>$16</span><p>Chipotle aioli, sweet soy, and scallions with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>PEI Mussels</strong> <span>$19</span><p>Coconut curry sauce, garlic crostini, and fine herbs.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Wings</strong> <span>$16</span><p>Classic fried chicken wings with Buffalo, sweet chili, BBQ, or jerk seasoning.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Chicken Tortilla Soup</strong> <span>$10</span><p>Roasted chicken, fire-roasted tomatoes, black beans, corn, and bell peppers with tortilla strips, cotija, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Summer Salad</strong> <span>$18</span><p>Arugula, pineapple and watermelon, shallot, feta, and grilled chicken in pineapple-cilantro vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Hampton Caesar</strong> <span>$18</span><p>Arugula and radicchio, lemon-thyme croutons, cotija, and grilled chicken in Caesar dressing.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Spinach + Chickpea</strong> <span>$18</span><p>Feta, pickled onion, cucumber, cherry tomato, and harissa pulled chicken in lemon-basil vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Carne Asada Taco</strong> <span>$4</span><p>Marinated sirloin steak, crispy shallots, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Beachfire Chicken Taco</strong> <span>$4</span><p>Buttermilk-fried chicken breast, Valentina hot sauce, spicy slaw, pickled jalapeños, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Carnitas Taco</strong> <span>$4</span><p>Slow-roasted pork, aguachile, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Seared Tuna Taco</strong> <span>$5</span><p>Toasted sesame seeds, Tajín-jicama, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Belly Taco</strong> <span>$5</span><p>Wakame seaweed salad, hoisin glaze, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Al Pastor Taco</strong> <span>$4</span><p>Crumbled chorizo, grilled pineapple, scallions, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Baja Fish Taco</strong> <span>$4</span><p>Beer-and-vodka-battered seasonal local fish, red cabbage, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Jerk Shrimp Taco</strong> <span>$5</span><p>Spicy slaw, pico de gallo, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Local Catch Taco</strong> <span>$4</span><p>Grilled seasonal local fish, red cabbage, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Roasted Cauliflower Taco</strong> <span>$4</span><p>Pickled onions, sweet soy, toasted sesame seeds, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Cheesy Mac</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Sautéed Spinach</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Cotija-Truffle Fries</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Black Beans</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Mashed Potatoes</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>White Rice</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Veggie Medley</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Gallo Pinto</strong> <span>$7</span><p>White rice, black beans, pico de gallo, cotija, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Poke Bowl</strong> <span>$26</span><p>Sushi rice, shredded carrots, cucumber, radish, marinated yellowfin tuna, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Mediterranean Bowl</strong> <span>$21</span><p>House-made hummus, grilled halloumi, cherry tomato, radish, cucumber, red onion, roasted garlic oil, and naan.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Zuma Beach Bowl</strong> <span>$21</span><p>Quinoa, vegetable medley, crunchy chickpeas, pickled onions, and lemon-basil vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Miyazaki Bowl</strong> <span>$26</span><p>Crispy pork, steamed white rice, cucumber, red cabbage, wakame seaweed salad, rice-wine vinaigrette, and fried egg.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Beach Kebabs</strong> <span>$28</span><p>Jumbo shrimp skewers with coconut-chorizo rice.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Quesadilla</strong> <span>$12</span><p>Grilled flour tortilla, mixed cheeses, and pico de gallo.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Roasted Chicken</strong> <span>$26</span><p>Served with mac and cheese, sautéed spinach, diced tomatoes, and fine herbs.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Sirloin Steak</strong> <span>$31</span><p>Served with mashed potatoes, sautéed spinach, and frizzled onions.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Fish + Chips</strong> <span>$23</span><p>Beer-battered seasonal local fish with crispy fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Coconut-Crusted Cod</strong> <span>$29</span><p>White rice, iceberg lettuce, green apple, cucumber, and sweet chili sauce.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Lobster Roll</strong> <span>$35</span><p>Hot: warm and buttery. Cold: tossed in herb aioli. Served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Big John Burger</strong> <span>$15</span><p>Seven-ounce tri-cut beef blend served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Big Al Burger</strong> <span>$18</span><p>Seven-ounce tri-cut beef blend, American cheese, bacon, lettuce, tomato, and onion; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Korean Chicken Sammy</strong> <span>$16</span><p>Fried chicken breast, spicy kimchi, cucumber, honey-gochujang, sesame seeds, and buttermilk ranch; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Maverick Burger</strong> <span>$21</span><p>Seven-ounce tri-cut beef blend, A1 aioli, crispy shallots, pork carnitas, and pepper jack; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Shrimp Po Boy</strong> <span>$20</span><p>Coconut-milk-marinated fried shrimp, shredded lettuce, tomato, and fried jalapeños; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Churros</strong> <span>$8</span><p>House-made churros with caramel and vanilla dipping sauces.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Ice Cream</strong> <span>$6</span><p>One scoop of vanilla ice cream.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Key Lime Pie</strong> <span>$8</span><p>Tangy key lime custard, graham cracker crust, whipped cream, and lime zest.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li></ul></section><section class="curriculum-block curriculum-source-control curriculum-status-verification-required"><h2>Allergy boundary</h2><p>Descriptions are not allergy certification. Never infer safety from an ingredient list, gluten-free label, cooking method, or past answer. Use the current allergy communication chain.</p><p><small>Sources: allergy-source-current</small></p></section><section class="curriculum-block curriculum-practice"><h2>Menu map</h2><p>Sort surprise items into category, give a truthful 15-second description, name who it might fit, and state where to verify modifications.</p><h3>Success criteria</h3><ul><li>Current item</li><li>Correct category</li><li>No invented ingredient</li><li>Useful sensory fit</li><li>No allergy assertion</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: Where is the Quesadilla listed on the supplied current dining menu?</li><li><strong>practical</strong>: Describe five random current menu items and handle one allergy question.</li></ol></section><footer><small>Sources: food-menu-supplied, allergy-source-current</small></footer></article>$curriculum_html$, 60, true, true, 30, ARRAY['server', 'menu', 'food', 'required', 'practical-required']::text[]),
  ('cur-server-beverage-menu', 'sec-server-onboarding', 'Cocktails, Zero Proof, Wine + Rotating Beer', 'Guide beverage decisions using current flavor lanes while respecting recipe locks and rotating selections.', 'server-beverage-menu', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-beverage-menu"><header><p class="curriculum-eyebrow">server / menu / beverage / required</p><h1>Cocktails, Zero Proof, Wine + Rotating Beer</h1><p>Guide beverage decisions using current flavor lanes while respecting recipe locks and rotating selections.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Describe current guest-facing cocktails</li><li>Recognize verification-required recipes</li><li>Verify beer in the current POS</li></ul></section><section class="curriculum-block curriculum-menu-reference"><h2>Current cocktail and zero-proof menu</h2><p>Servers learn guest-facing ingredients and flavor lanes. Only bartenders train measured builds, and verification-required recipes remain locked until manager approval.</p><ul><li><strong>Hang 10 Marg</strong> <span>$13.24</span><p>Reposado tequila, orange liqueur, fresh lime and lemon juices, house sugar syrup, and a salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Smoke on the Bay</strong> <span>$14.78</span><p>Tanteo Chipotle, 400 Conejos mezcal, fresh lime, watermelon, house sugar syrup, and a black lava salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Holla Pain Yo!</strong> <span>$14.78</span><p>Tanteo Jalapeño, fresh lime juice, house sugar syrup, and a Tajín rim.</p><p><small>Source status: approved</small></p></li><li><strong>Mo Pain Yo!</strong> <span>$14.78</span><p>Tanteo Jalapeño and Habanero, fresh lime juice, house sugar syrup, and a Tajín rim.</p><p><small>Source status: approved</small></p></li><li><strong>Pineapple Basil Smash</strong> <span>$14.78</span><p>Reposado tequila, basil, cucumber, pineapple, and fresh lemon juice.</p><p><small>Source status: approved</small></p></li><li><strong>Oaxaca Mule</strong> <span>$14.78</span><p>Reposado tequila, 400 Conejos mezcal, artichoke liqueur, fresh lime, house sugar syrup, mint, and ginger beer.</p><p><small>Source status: approved</small></p></li><li><strong>Ancho Average Marg</strong> <span>$29.51</span><p>A share cocktail for two with Tanteo Chipotle, reposado tequila, citrus, pineapple, house sugar syrup, and a Tajín rim.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> The controlled source contains an apparent Tanteo Chipotle quantity typo. A manager must lock the correct build before training; do not teach the printed quantity.</p></li><li><strong>Cool as a Cucumber</strong> <span>$13.24</span><p>Vodka, melon liqueur, cucumber, fresh lime, house sugar syrup, and tonic.</p><p><small>Source status: approved</small></p></li><li><strong>Sunburnt Summer</strong> <span>$14.78</span><p>Gin, Chartreuse, fresh lime, house sugar syrup, strawberry, and basil.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> Verify the full current build and recipe-lock initials before training.</p></li><li><strong>Frozen Paloma</strong> <span>$13.24</span><p>Reposado tequila, orange and grapefruit liqueurs, citrus, house sugar syrup, and a pink-peppercorn salt rim.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> Verify the approved batch, pink-peppercorn salt, machine standard, and recipe-lock initials before training.</p></li><li><strong>Da Painkiller</strong> <span>$13.24</span><p>Pusser&#039;s Navy Strength and Gunpowder Proof rums, Coco Lopez, pineapple and orange juices, and nutmeg.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> Verify the full current build and recipe-lock initials before training.</p></li><li><strong>Island Rum Punch</strong> <span>$13.24</span><p>White and dark rums, house falernum, fresh lime, pineapple, passionfruit, mango, and house sugar syrup.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> The controlled manual flags an almond concern through house falernum. Verify the current build and current approved allergy source with a manager before training or answering a guest.</p></li><li><strong>Mojito</strong> <span>$13.24</span><p>White rum, fresh lime, house sugar syrup, mint, and soda.</p><p><small>Source status: approved</small></p></li><li><strong>Watermelon Cooler</strong> <span>$6.18</span><p>Watermelon, fresh lime, pineapple juice, and mint.</p><p><small>Source status: approved</small></p></li><li><strong>No-Jito</strong> <span>$6.18</span><p>Fresh lime, apple juice, house sugar syrup, mint, and soda.</p><p><small>Source status: approved</small></p></li><li><strong>Piña No-Lada</strong> <span>$6.18</span><p>Coco Lopez, fresh lime, and pineapple juice.</p><p><small>Source status: approved</small></p></li><li><strong>Hibiscus Refresher</strong> <span>$6.18</span><p>Hibiscus syrup, coconut water, fresh lime, and mango.</p><p><small>Source status: verification-required</small></p><p><strong>Verify:</strong> Verify the approved syrup/product, open-life, full build, and recipe-lock initials before training.</p></li></ul></section><section class="curriculum-block curriculum-source-control curriculum-status-rotating"><h2>Rotating beer</h2><p>Selections change. Demonstrate the live verification path in the location&#039;s POS or current manager-posted list.</p><p><small>Sources: beer-source-current</small></p></section><section class="curriculum-block curriculum-practice"><h2>Beverage lanes</h2><p>Guide bright/classic, smoky/spicy, herbal/tropical, and zero-proof guest profiles using current items.</p><h3>Success criteria</h3><ul><li>Asks before choosing</li><li>Uses current flavor lane</li><li>Does not teach locked recipe</li><li>Offers zero proof with equal hospitality</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which current drink is the classic, bright starting point?</li><li><strong>practical</strong>: Guide four beverage profiles and show where the current beer list is verified.</li></ol></section><footer><small>Sources: cocktail-menu-supplied, bar-manual-2026-08, beer-source-current</small></footer></article>$curriculum_html$, 45, true, true, 40, ARRAY['server', 'menu', 'beverage', 'required', 'practical-required']::text[]),
  ('cur-server-passion-selling', 'sec-server-onboarding', 'Server Passion Selling', 'Use Observe > Ask > Interpret > Recommend > Describe at the table without pressure.', 'server-passion-selling', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-passion-selling"><header><p class="curriculum-eyebrow">server / passion-selling / required</p><h1>Server Passion Selling</h1><p>Use Observe &gt; Ask &gt; Interpret &gt; Recommend &gt; Describe at the table without pressure.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Ask an efficient preference question</li><li>Take a point of view</li><li>Offer current pairings for a reason</li></ul></section><section class="curriculum-block curriculum-steps"><h2>The formula</h2><ol><li>Observe the guest&#039;s cues</li><li>Ask one useful question</li><li>Interpret the preference</li><li>Recommend one direction</li><li>Describe why it fits</li></ol></section><section class="curriculum-block curriculum-menu-reference"><h2>Verified practice pairings</h2><p>Use pairings as conversation starters only when they fit the guest. State the flavor reason; do not push.</p><ul><li><strong>Yuca Poppers</strong> <span>$14</span><p>Fried yuca croquettes with guacamole, sweet chili, herb aioli, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Hang 10 Marg</strong> <span>$13.24</span><p>Reposado tequila, orange liqueur, fresh lime and lemon juices, house sugar syrup, and a salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Carne Asada Taco</strong> <span>$4</span><p>Marinated sirloin steak, crispy shallots, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Smoke on the Bay</strong> <span>$14.78</span><p>Tanteo Chipotle, 400 Conejos mezcal, fresh lime, watermelon, house sugar syrup, and a black lava salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Jerk Shrimp Taco</strong> <span>$5</span><p>Spicy slaw, pico de gallo, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pineapple Basil Smash</strong> <span>$14.78</span><p>Reposado tequila, basil, cucumber, pineapple, and fresh lemon juice.</p><p><small>Source status: approved</small></p></li><li><strong>Wings</strong> <span>$16</span><p>Classic fried chicken wings with Buffalo, sweet chili, BBQ, or jerk seasoning.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Oaxaca Mule</strong> <span>$14.78</span><p>Reposado tequila, 400 Conejos mezcal, artichoke liqueur, fresh lime, house sugar syrup, mint, and ginger beer.</p><p><small>Source status: approved</small></p></li></ul></section><section class="curriculum-block curriculum-practice"><h2>One size fits one</h2><p>Guide a first-time sharer, a light-appetite guest, a spice-seeker, and a zero-proof guest.</p><h3>Success criteria</h3><ul><li>Question shapes recommendation</li><li>Current facts</li><li>Right-sized</li><li>Truthful contrast</li><li>Natural language</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the best response to &#039;What&#039;s good?&#039;</li><li><strong>practical</strong>: Complete four 20-second recommendation role-plays.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, food-menu-supplied, bar-manual-2026-08</small></footer></article>$curriculum_html$, 40, true, true, 50, ARRAY['server', 'passion-selling', 'required', 'practical-required']::text[]),
  ('cur-server-pos-pacing-safety', 'sec-server-onboarding', 'POS Accuracy, Pacing + Allergy Communication', 'Translate the guest''s order into an accurate, timed, safely communicated handoff.', 'server-pos-pacing-safety', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-pos-pacing-safety"><header><p class="curriculum-eyebrow">server / pos / allergy / safety / required</p><h1>POS Accuracy, Pacing + Allergy Communication</h1><p>Translate the guest&#039;s order into an accurate, timed, safely communicated handoff.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Enter current modifiers accurately</li><li>Use seat/course/timing communication</li><li>Execute the complete allergy escalation chain</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Accuracy loop</h2><ul><li>Clarify the request</li><li>Repeat material modifications</li><li>Use the current POS button/modifier</li><li>Set course and seat information</li><li>Verbally communicate critical information</li><li>Watch ticket flow</li><li>Confirm delivery and check back</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Allergy chain</h2><ol><li>Acknowledge without promising</li><li>Mark the current POS procedure</li><li>Communicate verbally</li><li>Involve the manager</li><li>Kitchen verifies what can be prepared safely</li><li>Confirm protected delivery/handoff</li></ol></section><section class="curriculum-block curriculum-scenario"><h2>Complex order</h2><p>Enter and hand off a three-course order with a modification, an allergy concern, and a guest deadline.</p><h3>Success criteria</h3><ul><li>No missed modifier</li><li>Allergy chain complete</li><li>Pacing realistic</li><li>Kitchen/support handoffs named</li><li>Guest updated</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>multiple-choice</strong>: What must happen in addition to marking an allergy in the POS?</li><li><strong>practical</strong>: Complete the complex-order simulation.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, allergy-source-current</small></footer></article>$curriculum_html$, 55, true, true, 60, ARRAY['server', 'pos', 'allergy', 'safety', 'required', 'practical-required']::text[]),
  ('cur-server-recovery-payment', 'sec-server-onboarding', 'Recovery, Payment + Strong Finish', 'Use L.A.S.T., protect role boundaries, close checks accurately, and end with genuine appreciation.', 'server-recovery-payment', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-recovery-payment"><header><p class="curriculum-eyebrow">server / recovery / payment / required</p><h1>Recovery, Payment + Strong Finish</h1><p>Use L.A.S.T., protect role boundaries, close checks accurately, and end with genuine appreciation.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Run a same-team recovery</li><li>Involve the MOD at the right moment</li><li>Complete payment and farewell without friction</li></ul></section><section class="curriculum-block curriculum-steps"><h2>L.A.S.T.</h2><ol><li>Listen fully</li><li>Apologize for the experience</li><li>Solve within role and manager boundaries</li><li>Think about prevention after care is restored</li></ol></section><section class="curriculum-block curriculum-checklist"><h2>Finish strong</h2><ul><li>Check accuracy before presenting</li><li>Process payment promptly</li><li>Follow current cash/card procedure</li><li>Return receipt/change cleanly</li><li>Reference the guest&#039;s experience</li><li>Thank sincerely</li><li>Acknowledge departure</li></ul></section><section class="curriculum-block curriculum-practice"><h2>Two recoveries + close</h2><p>Recover a delayed item and a guest dislike, then close the check and farewell.</p><h3>Success criteria</h3><ul><li>No blame</li><li>Solution is honest</li><li>MOD involved when required</li><li>Specific follow-up</li><li>Accurate payment</li><li>Warm close</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What comes after a recovery solution?</li><li><strong>practical</strong>: Complete the recovery and payment role-play.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, leadership-os-1</small></footer></article>$curriculum_html$, 40, true, true, 70, ARRAY['server', 'recovery', 'payment', 'required', 'practical-required']::text[]),
  ('cur-server-final-practical', 'sec-server-onboarding', 'Server Final Practical', 'Prove independent table ownership in a realistic sequence and survive a 7/30-day audit.', 'server-final-practical', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-server-final-practical"><header><p class="curriculum-eyebrow">server / certification / final-practical / required</p><h1>Server Final Practical</h1><p>Prove independent table ownership in a realistic sequence and survive a 7/30-day audit.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Prepare a section</li><li>Own a full realistic table</li><li>Demonstrate source safety and recovery</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Final practicum</h2><p>Prepare a section; greet and discover; guide a current menu decision; enter and course an order; communicate an allergy; handle a recovery; complete payment, sidework, and handoff.</p><h3>Success criteria</h3><ul><li>Knowledge proof</li><li>Independent performance</li><li>No critical miss</li><li>Trainer does not carry result</li><li>7- and 30-day audit scheduled</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>short-answer</strong>: Teach back the guest journey, CARE, Passion Selling, allergy chain, and L.A.S.T.</li><li><strong>practical</strong>: Complete the server final practicum.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1, food-menu-supplied, bar-manual-2026-08</small></footer></article>$curriculum_html$, 75, true, true, 80, ARRAY['server', 'certification', 'final-practical', 'required', 'practical-required']::text[]),
  ('cur-bartender-identity-journey', 'sec-bartender-onboarding', 'Bar Identity + Guest Journey', 'Be host, craftsperson, traffic controller, and good-vibe mechanic with warm people and exact execution.', 'bartender-identity-guest-journey', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-identity-journey"><header><p class="curriculum-eyebrow">bartender / onboarding / required</p><h1>Bar Identity + Guest Journey</h1><p>Be host, craftsperson, traffic controller, and good-vibe mechanic with warm people and exact execution.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Acknowledge new guests within 30 seconds</li><li>Run discover-to-close sequence</li><li>Own the ticket, pace, cleanup, and handoff</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>The bar standard</h2><p>Hospitality without standards is chaos. Standards without hospitality is a vending machine. Ditch needs warm people and exact execution.</p></section><section class="curriculum-block curriculum-steps"><h2>Bar guest journey</h2><ol><li>0-30 seconds: acknowledge</li><li>Discover one useful preference</li><li>Recommend one confident choice and reason</li><li>Build and deliver to spec</li><li>Two-sip check</li><li>Continue, pace water/food/alcohol, close accurately, and say goodbye</li></ol></section><section class="curriculum-block curriculum-practice"><h2>Buried-but-visible</h2><p>Acknowledge three arrivals while managing a ticket rail without making a promise you cannot keep.</p><h3>Success criteria</h3><ul><li>Every guest seen</li><li>Next step stated</li><li>Tickets stay accurate</li><li>Tone remains calm</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the acknowledgment target at the bar?</li><li><strong>practical</strong>: Run the buried-but-visible scenario.</li></ol></section><footer><small>Sources: bar-manual-2026-08, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 30, true, true, 10, ARRAY['bartender', 'onboarding', 'required', 'practical-required']::text[]),
  ('cur-bartender-safe-responsible', 'sec-bartender-onboarding', 'Safe + Responsible Service', 'Protect ID, intoxication, allergy, glass/ice, and incident boundaries without improvisation.', 'bartender-safe-responsible-service', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-safe-responsible"><header><p class="curriculum-eyebrow">bartender / safety / alcohol / allergy / required</p><h1>Safe + Responsible Service</h1><p>Protect ID, intoxication, allergy, glass/ice, and incident boundaries without improvisation.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Own the ID decision</li><li>Use current responsible-service escalation</li><li>Execute the allergy and broken-glass stop points</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-warning"><h2>Never transfer the ID responsibility</h2><p>The employee serving alcohol remains responsible for checking identification even when security is present. Use current law and company policy; involve the MOD before risk grows.</p></section><section class="curriculum-block curriculum-checklist"><h2>Critical stop points</h2><ul><li>Uncertain or invalid ID</li><li>Signs of intoxication or rapid consumption</li><li>Allergy uncertainty</li><li>Broken glass in or near ice</li><li>Unsafe spill or equipment condition</li><li>Conflict or security concern</li></ul></section><section class="curriculum-block curriculum-scenario"><h2>Responsible-service triad</h2><p>Handle a questionable ID, a guest showing impairment, and an allergy question without guessing or escalating emotion.</p><h3>Success criteria</h3><ul><li>Follows current policy</li><li>MOD involved promptly</li><li>Same-team language</li><li>Incident/handoff documented as required</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>true-false</strong>: Security checking an ID removes the bartender&#039;s responsibility.</li><li><strong>practical</strong>: Complete the responsible-service triad.</li></ol></section><footer><small>Sources: bar-manual-2026-08, allergy-source-current</small></footer></article>$curriculum_html$, 50, true, true, 20, ARRAY['bartender', 'safety', 'alcohol', 'allergy', 'required', 'practical-required']::text[]),
  ('cur-bartender-station-technique', 'sec-bartender-onboarding', 'Station Readiness + Build Technique', 'Set the station once, jigger every pour, use fresh ice, and make repeatability visible.', 'bartender-station-technique', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-station-technique"><header><p class="curriculum-eyebrow">bartender / technique / station / required</p><h1>Station Readiness + Build Technique</h1><p>Set the station once, jigger every pour, use fresh ice, and make repeatability visible.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Verify the approved well and back-bar layout</li><li>Choose the correct method</li><li>Build cleanly with controlled dilution and finish</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Station standard</h2><ul><li>Both wells mirror approved setup</li><li>Bottles returned to labeled locations</li><li>Tools clean and at home</li><li>Fresh hard ice</li><li>Correct glassware and garnish</li><li>Backups, labels, and dates verified</li><li>Dry floor and clear paths</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Build discipline</h2><ol><li>Read the complete ticket and modifiers</li><li>Add lower-cost modifiers first and base spirit after</li><li>Add ice last</li><li>Jigger every pour</li><li>Shake/stir with clean hard ice</li><li>Serve over fresh ice unless recipe explicitly says dump/pour</li><li>Add carbonation after shaking/stirring</li><li>Wipe the vessel and present the clean rim</li></ol></section><section class="curriculum-block curriculum-practice"><h2>Technique stations</h2><p>Demonstrate build, shake, stir, double strain, top, frozen-service check, draft pour, and wine-pour verification.</p><h3>Success criteria</h3><ul><li>Method matches source</li><li>No reused shaker ice</li><li>Carbonation handled last</li><li>Wine pour uses current verified measure</li><li>Station resets between reps</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: When is carbonation normally added?</li><li><strong>practical</strong>: Complete the technique stations and full reset.</li></ol></section><footer><small>Sources: bar-manual-2026-08</small></footer></article>$curriculum_html$, 60, true, true, 30, ARRAY['bartender', 'technique', 'station', 'required', 'practical-required']::text[]),
  ('cur-bartender-approved-signatures-1', 'sec-bartender-onboarding', 'Approved Signatures I: Margarita Lane', 'Build the approved current margaritas exactly: glass, ice, method, ounces, rim, and garnish.', 'approved-signatures-margaritas', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-approved-signatures-1"><header><p class="curriculum-eyebrow">bartender / recipes / margaritas / required</p><h1>Approved Signatures I: Margarita Lane</h1><p>Build the approved current margaritas exactly: glass, ice, method, ounces, rim, and garnish.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Build Hang 10, Smoke on the Bay, Holla Pain Yo!, and Mo Pain Yo! from memory</li><li>Explain the flavor contrast</li><li>Warn accurately about the hotter spicy option</li></ul></section><section class="curriculum-block curriculum-menu-reference"><h2>Approved recipe set</h2><p>Use every measured build, method, rim, garnish, and glass exactly as listed in the controlled curriculum.</p><ul><li><strong>Hang 10 Marg</strong> <span>$13.24</span><p>Reposado tequila, orange liqueur, fresh lime and lemon juices, house sugar syrup, and a salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Smoke on the Bay</strong> <span>$14.78</span><p>Tanteo Chipotle, 400 Conejos mezcal, fresh lime, watermelon, house sugar syrup, and a black lava salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Holla Pain Yo!</strong> <span>$14.78</span><p>Tanteo Jalapeño, fresh lime juice, house sugar syrup, and a Tajín rim.</p><p><small>Source status: approved</small></p></li><li><strong>Mo Pain Yo!</strong> <span>$14.78</span><p>Tanteo Jalapeño and Habanero, fresh lime juice, house sugar syrup, and a Tajín rim.</p><p><small>Source status: approved</small></p></li></ul></section><section class="curriculum-block curriculum-comparison"><h2>Spice guidance</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Holla Pain Yo!</th><th>Mo Pain Yo!</th></tr></thead><tbody><tr><td>Jalapeño, tart, lively</td><td>Jalapeño plus habanero; explicitly the hotter option</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-practice"><h2>Four-drink practical</h2><p>Build all four in random order from memory, then identify one planted finish or measurement miss.</p><h3>Success criteria</h3><ul><li>Exact ounces</li><li>Correct method and fresh ice</li><li>Correct rim/garnish</li><li>Clean presentation</li><li>Station reset</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which verified spicy marg uses both jalapeño and habanero?</li><li><strong>practical</strong>: Pass the random four-drink build practical.</li></ol></section><footer><small>Sources: bar-manual-2026-08, cocktail-menu-supplied</small></footer></article>$curriculum_html$, 80, true, true, 40, ARRAY['bartender', 'recipes', 'margaritas', 'required', 'practical-required']::text[]),
  ('cur-bartender-approved-signatures-2', 'sec-bartender-onboarding', 'Approved Signatures II: House + Zero Proof', 'Build the currently approved herbal, refreshing, rum, and zero-proof signatures with equal care.', 'approved-signatures-house-zero-proof', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-approved-signatures-2"><header><p class="curriculum-eyebrow">bartender / recipes / zero-proof / required</p><h1>Approved Signatures II: House + Zero Proof</h1><p>Build the currently approved herbal, refreshing, rum, and zero-proof signatures with equal care.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Build six approved signatures</li><li>Handle herbs and carbonation correctly</li><li>Give zero-proof guests the full hospitality experience</li></ul></section><section class="curriculum-block curriculum-menu-reference"><h2>Approved recipe set</h2><p>Train only these approved builds in this module. Use fresh herbs, correct carbonation order, exact finish, and a clean reset.</p><ul><li><strong>Pineapple Basil Smash</strong> <span>$14.78</span><p>Reposado tequila, basil, cucumber, pineapple, and fresh lemon juice.</p><p><small>Source status: approved</small></p></li><li><strong>Oaxaca Mule</strong> <span>$14.78</span><p>Reposado tequila, 400 Conejos mezcal, artichoke liqueur, fresh lime, house sugar syrup, mint, and ginger beer.</p><p><small>Source status: approved</small></p></li><li><strong>Cool as a Cucumber</strong> <span>$13.24</span><p>Vodka, melon liqueur, cucumber, fresh lime, house sugar syrup, and tonic.</p><p><small>Source status: approved</small></p></li><li><strong>Mojito</strong> <span>$13.24</span><p>White rum, fresh lime, house sugar syrup, mint, and soda.</p><p><small>Source status: approved</small></p></li><li><strong>Watermelon Cooler</strong> <span>$6.18</span><p>Watermelon, fresh lime, pineapple juice, and mint.</p><p><small>Source status: approved</small></p></li><li><strong>No-Jito</strong> <span>$6.18</span><p>Fresh lime, apple juice, house sugar syrup, mint, and soda.</p><p><small>Source status: approved</small></p></li><li><strong>Piña No-Lada</strong> <span>$6.18</span><p>Coco Lopez, fresh lime, and pineapple juice.</p><p><small>Source status: approved</small></p></li></ul></section><section class="curriculum-block curriculum-practice"><h2>Random build + guest guidance</h2><p>Build four random items, including one zero-proof, and guide a guest through the flavor difference.</p><h3>Success criteria</h3><ul><li>Exact source</li><li>Herbs handled cleanly</li><li>Carbonation last</li><li>Zero proof receives equal presentation</li><li>Guest language is current and human</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: Which approved cocktail is topped with ginger beer after double straining?</li><li><strong>practical</strong>: Complete the random build and guidance practical.</li></ol></section><footer><small>Sources: bar-manual-2026-08, cocktail-menu-supplied</small></footer></article>$curriculum_html$, 95, true, true, 50, ARRAY['bartender', 'recipes', 'zero-proof', 'required', 'practical-required']::text[]),
  ('cur-bartender-locked-rotating', 'sec-bartender-onboarding', 'Recipe Locks + Rotating Products', 'Recognize when the safe, professional answer is to stop, verify, and update the source.', 'verification-required-rotating-content', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-locked-rotating"><header><p class="curriculum-eyebrow">bartender / source-control / verification-required / required</p><h1>Recipe Locks + Rotating Products</h1><p>Recognize when the safe, professional answer is to stop, verify, and update the source.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Identify every verification-required recipe</li><li>Avoid the Ancho quantity typo</li><li>Verify beer, wine pour, pars, and recipe locks</li></ul></section><section class="curriculum-block curriculum-source-control curriculum-status-verification-required"><h2>Do not train until locked</h2><p>Ancho Average Marg, Sunburnt Summer, Frozen Paloma, Da Painkiller, Island Rum Punch, and Hibiscus Refresher require manager approval on the recipe lock. The Ancho printed Tanteo quantity is an apparent source error and must not be taught. Pink salt, measured wine pour, and current pars also require verification where the source flags conflict.</p><p><small>Sources: bar-manual-2026-08</small></p></section><section class="curriculum-block curriculum-source-control curriculum-status-rotating"><h2>Rotating beer</h2><p>Current POS and the manager-posted list win. Demonstrate the verification path; do not certify a historic six-beer list.</p><p><small>Sources: beer-source-current</small></p></section><section class="curriculum-block curriculum-scenario"><h2>Source conflict</h2><p>A teammate quotes an old recipe, the printed manual conflicts, and a guest is waiting. Protect the guest while resolving the source.</p><h3>Success criteria</h3><ul><li>Stops the guess</li><li>Uses manager/current lock</li><li>Sets honest guest expectation</li><li>Updates/escalates source mismatch</li><li>Does not create a local workaround</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>multi-select</strong>: Which items remain verification-required?</li><li><strong>practical</strong>: Resolve the source-conflict scenario and show the current beer verification path.</li></ol></section><footer><small>Sources: bar-manual-2026-08, beer-source-current, allergy-source-current</small></footer></article>$curriculum_html$, 35, true, true, 60, ARRAY['bartender', 'source-control', 'verification-required', 'required', 'practical-required']::text[]),
  ('cur-bartender-passion-pairing', 'sec-bartender-onboarding', 'Bar Passion Selling + Pairing', 'Discover the guest''s flavor lane and recommend with a current, truthful reason.', 'bartender-passion-selling-pairing', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-passion-pairing"><header><p class="curriculum-eyebrow">bartender / passion-selling / pairing / required</p><h1>Bar Passion Selling + Pairing</h1><p>Discover the guest&#039;s flavor lane and recommend with a current, truthful reason.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use one useful beverage question</li><li>Recommend across spirited and zero-proof lanes</li><li>Pair only current approved items</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Discover the lane</h2><ol><li>Bright and refreshing</li><li>Smoky and spicy</li><li>Herbal and tropical</li><li>Spirit-forward</li><li>Beer or wine</li><li>Zero proof</li></ol></section><section class="curriculum-block curriculum-menu-reference"><h2>Approved pairing lab</h2><p>Explain the flavor reason. Availability, allergy safety, and preference still require current verification.</p><ul><li><strong>Hang 10 Marg</strong> <span>$13.24</span><p>Reposado tequila, orange liqueur, fresh lime and lemon juices, house sugar syrup, and a salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Yuca Poppers</strong> <span>$14</span><p>Fried yuca croquettes with guacamole, sweet chili, herb aioli, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Baja Fish Taco</strong> <span>$4</span><p>Beer-and-vodka-battered seasonal local fish, red cabbage, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Smoke on the Bay</strong> <span>$14.78</span><p>Tanteo Chipotle, 400 Conejos mezcal, fresh lime, watermelon, house sugar syrup, and a black lava salt rim.</p><p><small>Source status: approved</small></p></li><li><strong>Carne Asada Taco</strong> <span>$4</span><p>Marinated sirloin steak, crispy shallots, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Belly Taco</strong> <span>$5</span><p>Wakame seaweed salad, hoisin glaze, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pineapple Basil Smash</strong> <span>$14.78</span><p>Reposado tequila, basil, cucumber, pineapple, and fresh lemon juice.</p><p><small>Source status: approved</small></p></li><li><strong>Jerk Shrimp Taco</strong> <span>$5</span><p>Spicy slaw, pico de gallo, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Tuna Tartare</strong> <span>$16</span><p>Chipotle aioli, sweet soy, and scallions with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Oaxaca Mule</strong> <span>$14.78</span><p>Reposado tequila, 400 Conejos mezcal, artichoke liqueur, fresh lime, house sugar syrup, mint, and ginger beer.</p><p><small>Source status: approved</small></p></li><li><strong>Pork Carnitas Taco</strong> <span>$4</span><p>Slow-roasted pork, aguachile, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Wings</strong> <span>$16</span><p>Classic fried chicken wings with Buffalo, sweet chili, BBQ, or jerk seasoning.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li></ul></section><section class="curriculum-block curriculum-practice"><h2>Four guest profiles</h2><p>Guide a vodka-soda regular, spice-seeker, food-pairing guest, and zero-proof guest.</p><h3>Success criteria</h3><ul><li>Asks before recommending</li><li>Takes a position</li><li>Current verified item</li><li>Pairing reason</li><li>No pressure</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What pairing reason is listed for Hang 10 with fried or rich food?</li><li><strong>practical</strong>: Complete four beverage-guidance role-plays.</li></ol></section><footer><small>Sources: bar-manual-2026-08, food-menu-supplied, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 40, true, true, 70, ARRAY['bartender', 'passion-selling', 'pairing', 'required', 'practical-required']::text[]),
  ('cur-bartender-ticket-recovery', 'sec-bartender-onboarding', 'Ticket Flow, Volume + Recovery', 'Stay fast by staying organized; communicate before guests chase and recover without blame.', 'bartender-ticket-flow-recovery', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-ticket-recovery"><header><p class="curriculum-eyebrow">bartender / volume / recovery / required</p><h1>Ticket Flow, Volume + Recovery</h1><p>Stay fast by staying organized; communicate before guests chase and recover without blame.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Prioritize a realistic rail</li><li>Use 10 for 10 without stopping the bar</li><li>Complete L.A.S.T. and same-team handoffs</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Volume control</h2><ul><li>Read full tickets and modifiers</li><li>Batch safe movements, never guesses</li><li>Communicate aging tickets</li><li>Reset tools and bottles in motion</li><li>Use named handoffs</li><li>Protect water, food, responsible service, and guest acknowledgment</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Recovery</h2><ol><li>Listen</li><li>Apologize without excuse</li><li>Solve within authority or hand to MOD</li><li>Return for a two-sip/specific check</li><li>Think about source, prep, ticket, or system cause</li></ol></section><section class="curriculum-block curriculum-practice"><h2>Rail simulation</h2><p>Manage a realistic mixed rail with one modifier, one delayed drink, one guest dislike, and one 10 for 10 reset.</p><h3>Success criteria</h3><ul><li>Priority and accuracy</li><li>Guests remain visible</li><li>No reused ice or shortcuts</li><li>Recovery complete</li><li>Station returns to standard</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What protects speed most reliably?</li><li><strong>practical</strong>: Pass the rail simulation.</li></ol></section><footer><small>Sources: bar-manual-2026-08, hospitality-reset-2026-08, leadership-os-1</small></footer></article>$curriculum_html$, 55, true, true, 80, ARRAY['bartender', 'volume', 'recovery', 'required', 'practical-required']::text[]),
  ('cur-bartender-open-close-control', 'sec-bartender-onboarding', 'Open, Close, Clean + Control', 'Leave the next bartender a verified station, not a scavenger hunt or a mystery batch.', 'bartender-open-close-control', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-open-close-control"><header><p class="curriculum-eyebrow">bartender / opening / closing / control / required</p><h1>Open, Close, Clean + Control</h1><p>Leave the next bartender a verified station, not a scavenger hunt or a mystery batch.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Complete opening and closing from current checklists</li><li>Use labels, FIFO, waste, and maintenance controls</li><li>Sign only work personally completed or verified</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Complete reset</h2><ul><li>Wells, bottles, tools, mats</li><li>Soda-gun nozzles and holsters</li><li>Sinks and glass washer</li><li>POS and cash handoff under current policy</li><li>Coolers, glassware, garnish, labels, and dates</li><li>Garbage, floors, visible clutter</li><li>Shortages/86s/maintenance communicated</li></ul></section><section class="curriculum-block curriculum-standard curriculum-tone-warning"><h2>Signature meaning</h2><p>Initial only what you personally completed or physically verified. False or repeated incomplete sign-offs are performance and integrity issues.</p></section><section class="curriculum-block curriculum-practice"><h2>Close-to-open audit</h2><p>Close a staged bar, then have another qualified person open it using only the approved checklist and recorded handoff.</p><h3>Success criteria</h3><ul><li>No hidden unfinished task</li><li>Counts and labels accurate</li><li>Equipment clean</li><li>Shortage and maintenance loops closed</li><li>Second person can open without rescue</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>true-false</strong>: Initialing a checklist means you completed or physically verified the work.</li><li><strong>practical</strong>: Complete the close-to-open audit.</li></ol></section><footer><small>Sources: bar-manual-2026-08, hospitality-reset-2026-08</small></footer></article>$curriculum_html$, 55, true, true, 90, ARRAY['bartender', 'opening', 'closing', 'control', 'required', 'practical-required']::text[]),
  ('cur-bartender-final-practical', 'sec-bartender-onboarding', 'Bartender Final Practical', 'Prove hospitality, recipe accuracy, safety, volume control, and station ownership as one complete performance.', 'bartender-final-practical', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-bartender-final-practical"><header><p class="curriculum-eyebrow">bartender / certification / final-practical / required</p><h1>Bartender Final Practical</h1><p>Prove hospitality, recipe accuracy, safety, volume control, and station ownership as one complete performance.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Open and verify a station</li><li>Produce assigned approved drinks accurately</li><li>Manage guest, safety, recovery, and close</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Final practicum</h2><p>Open and verify; complete a random approved recipe practical; manage a realistic ticket rail; guide three guest preferences including zero proof; respond to an allergy and responsible-service scenario; close and document the station.</p><h3>Success criteria</h3><ul><li>Knowledge</li><li>Independent performance</li><li>Consistency</li><li>No locked recipe taught</li><li>No critical miss</li><li>7- and 30-day audit</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>short-answer</strong>: Teach back the bar guest journey, source hierarchy, approved vs. locked recipes, and critical stop points.</li><li><strong>practical</strong>: Complete the bartender final practicum.</li></ol></section><footer><small>Sources: bar-manual-2026-08, hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 120, true, true, 100, ARRAY['bartender', 'certification', 'final-practical', 'required', 'practical-required']::text[]),
  ('cur-support-shared-core', 'sec-support-onboarding', 'Support Identity + Shared Core', 'Make hospitality feel effortless by protecting welcome, accuracy, pace, cleanliness, readiness, and communication.', 'support-shared-core', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-shared-core"><header><p class="curriculum-eyebrow">support / onboarding / required</p><h1>Support Identity + Shared Core</h1><p>Make hospitality feel effortless by protecting welcome, accuracy, pace, cleanliness, readiness, and communication.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use CARE and five-foot ownership</li><li>Move with urgency without panic</li><li>Understand shared core and branch certification</li></ul></section><section class="curriculum-block curriculum-principle curriculum-tone-navy"><h2>Role mission</h2><p>Protect the guest experience underneath the visible service: welcome, accurate food, water, clean tables, safe movement, and closed communication loops.</p></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>Branch certification</h2><p>Every Support Staff teammate proves the shared core, then certifies separately for Host, Busser, Food Runner/Expo, or Barback duties. Cross-training adds proof; it does not transfer automatically.</p></section><section class="curriculum-block curriculum-practice"><h2>Five-foot ownership</h2><p>Identify five support needs in a staged room and prioritize them.</p><h3>Success criteria</h3><ul><li>Safety and food first</li><li>Arrival and guest visibility</li><li>Named handoffs</li><li>No panic</li><li>Own role remains covered</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>true-false</strong>: Certification in one support branch automatically certifies every branch.</li><li><strong>practical</strong>: Complete the staged-room priority drill.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 30, true, true, 10, ARRAY['support', 'onboarding', 'required', 'practical-required']::text[]),
  ('cur-support-safety-map', 'sec-support-onboarding', 'Safety, Restaurant Map + Communication', 'Know the room, table numbers, traffic paths, tools, hazards, and exact language for a clean handoff.', 'support-safety-map-communication', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-safety-map"><header><p class="curriculum-eyebrow">support / safety / communication / required</p><h1>Safety, Restaurant Map + Communication</h1><p>Know the room, table numbers, traffic paths, tools, hazards, and exact language for a clean handoff.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Navigate table/station map</li><li>Handle hot plates, glass, spills, lifting, and chemicals safely</li><li>Use names, table numbers, and exact actions</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Critical hazards</h2><ul><li>Hot plate and tray handling</li><li>Broken glass and ice</li><li>Wet floors and spills</li><li>Chemical labels and separation</li><li>Safe lifting and traffic flow</li><li>Allergy callouts</li><li>Guest-area hazards</li></ul></section><section class="curriculum-block curriculum-script"><h2>Closed-loop language</h2><blockquote><p>Alex, hot food for 24 needs a runner now - can you own it?</p><p>Heard - table 24, I have it.</p><p>Confirmed delivered; table still needs one item and the server knows.</p></blockquote></section><section class="curriculum-block curriculum-practice"><h2>Map and hazards</h2><p>Navigate surprise tables, carry/announce safely, correct two staged hazards, and complete a named handoff.</p><h3>Success criteria</h3><ul><li>Correct destination</li><li>Safe path</li><li>Exact language</li><li>Hazard not walked past</li><li>Handoff verified</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>multiple-choice</strong>: What should a support handoff include?</li><li><strong>practical</strong>: Complete the map, hazard, and handoff practical.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, allergy-source-current</small></footer></article>$curriculum_html$, 45, true, true, 20, ARRAY['support', 'safety', 'communication', 'required', 'practical-required']::text[]),
  ('cur-support-host-branch', 'sec-support-onboarding', 'Host Branch: Welcome + Flow', 'Make every arrival visible, quote waits honestly, seat with judgment, and transfer the table cleanly.', 'support-host-branch', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-host-branch"><header><p class="curriculum-eyebrow">support / host / branch-certification</p><h1>Host Branch: Welcome + Flow</h1><p>Make every arrival visible, quote waits honestly, seat with judgment, and transfer the table cleanly.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Acknowledge every arrival</li><li>Use current reservation/wait procedure</li><li>Complete host-to-server handoff</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Host journey</h2><ol><li>Acknowledge immediately</li><li>Learn name, party, needs, and context</li><li>Use current reservation/wait system</li><li>Quote honestly and update before being chased</li><li>Seat with table/section/accessibility awareness</li><li>Provide menus and a warm transfer</li><li>Confirm the table is acknowledged</li></ol></section><section class="curriculum-block curriculum-scenario"><h2>Arrival stack</h2><p>Manage a reservation, walk-in, phone call, and accessibility request arriving together.</p><h3>Success criteria</h3><ul><li>Everyone acknowledged</li><li>Priority explained</li><li>Wait quote honest</li><li>Accessibility protected</li><li>Server handoff closed</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: A guest may wait during volume, but should never...</li><li><strong>practical</strong>: Complete the arrival-stack practical.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 55, true, true, 30, ARRAY['support', 'host', 'branch-certification', 'practical-required']::text[]),
  ('cur-support-busser-branch', 'sec-support-onboarding', 'Busser Branch: Maintain + Reset', 'Read clearing cues, maintain water and the tabletop, and return the whole zone to guest-ready standard.', 'support-busser-branch', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-busser-branch"><header><p class="curriculum-eyebrow">support / busser / branch-certification</p><h1>Busser Branch: Maintain + Reset</h1><p>Read clearing cues, maintain water and the tabletop, and return the whole zone to guest-ready standard.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Pre-bus without interrupting the moment</li><li>Execute a complete reset</li><li>Keep dish flow and surrounding zone safe</li></ul></section><section class="curriculum-block curriculum-checklist"><h2>Complete reset</h2><ul><li>Read the clearing cue</li><li>Remove debris safely</li><li>Clean and dry full surface and seating</li><li>Replace approved settings in mapped positions</li><li>Check floor and surrounding zone</li><li>Confirm the table is truly ready</li></ul></section><section class="curriculum-block curriculum-practice"><h2>Three resets</h2><p>Complete one routine reset, one volume reset, and one reset with a staged surrounding-zone miss.</p><h3>Success criteria</h3><ul><li>No rushed safety miss</li><li>Surface and seating complete</li><li>Settings accurate</li><li>Floor/zone checked</li><li>Table released as ready</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>true-false</strong>: A reset is complete once the tabletop is wiped.</li><li><strong>practical</strong>: Complete three resets to standard.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 50, true, true, 40, ARRAY['support', 'busser', 'branch-certification', 'practical-required']::text[]),
  ('cur-support-runner-branch', 'sec-support-onboarding', 'Food Runner + Expo Branch: Accuracy at the Pass', 'Protect item, table, seat, allergy callout, temperature, presentation, and missing-item recovery.', 'support-food-runner-expo-branch', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-runner-branch"><header><p class="curriculum-eyebrow">support / runner / expo / branch-certification</p><h1>Food Runner + Expo Branch: Accuracy at the Pass</h1><p>Protect item, table, seat, allergy callout, temperature, presentation, and missing-item recovery.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Read current tickets accurately</li><li>Identify current menu items without guessing</li><li>Announce, deliver, and recover missing items safely</li></ul></section><section class="curriculum-block curriculum-menu-reference"><h2>Food identification</h2><p>Recognize current names and visible presentation from approved live training. Do not infer hidden ingredients or allergy safety from appearance.</p><ul><li><strong>Chips + Guac</strong> <span>$12</span><p>Mashed avocado, fresh lime juice, onion, tomato, cilantro, and pickled jalapeños with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Yuca Poppers</strong> <span>$14</span><p>Fried yuca croquettes with guacamole, sweet chili, herb aioli, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Empanada del Día</strong> <span>$14</span><p>The daily empanada served with herb aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Longboard Mozz Sticks</strong> <span>$10</span><p>House-made panko-breaded mozzarella with marinara.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Queso Blanco</strong> <span>$11</span><p>Queso with charred poblano and jalapeño peppers, served with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Carnitas Nachos</strong> <span>$18</span><p>Corn tortilla chips, queso blanco, pico de gallo, shredded lettuce, lime crema, and pickled jalapeños.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Crispy Calamari</strong> <span>$20</span><p>Topped with toasted coconut and scallions; served with sweet Thai chili sauce.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Fried Pickles</strong> <span>$8</span><p>House-made beer-battered pickle chips with horseradish aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Tuna Tartare</strong> <span>$16</span><p>Chipotle aioli, sweet soy, and scallions with corn tortilla chips.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>PEI Mussels</strong> <span>$19</span><p>Coconut curry sauce, garlic crostini, and fine herbs.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Wings</strong> <span>$16</span><p>Classic fried chicken wings with Buffalo, sweet chili, BBQ, or jerk seasoning.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Chicken Tortilla Soup</strong> <span>$10</span><p>Roasted chicken, fire-roasted tomatoes, black beans, corn, and bell peppers with tortilla strips, cotija, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Summer Salad</strong> <span>$18</span><p>Arugula, pineapple and watermelon, shallot, feta, and grilled chicken in pineapple-cilantro vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Hampton Caesar</strong> <span>$18</span><p>Arugula and radicchio, lemon-thyme croutons, cotija, and grilled chicken in Caesar dressing.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Spinach + Chickpea</strong> <span>$18</span><p>Feta, pickled onion, cucumber, cherry tomato, and harissa pulled chicken in lemon-basil vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Carne Asada Taco</strong> <span>$4</span><p>Marinated sirloin steak, crispy shallots, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Beachfire Chicken Taco</strong> <span>$4</span><p>Buttermilk-fried chicken breast, Valentina hot sauce, spicy slaw, pickled jalapeños, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Carnitas Taco</strong> <span>$4</span><p>Slow-roasted pork, aguachile, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Seared Tuna Taco</strong> <span>$5</span><p>Toasted sesame seeds, Tajín-jicama, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Pork Belly Taco</strong> <span>$5</span><p>Wakame seaweed salad, hoisin glaze, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Al Pastor Taco</strong> <span>$4</span><p>Crumbled chorizo, grilled pineapple, scallions, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Baja Fish Taco</strong> <span>$4</span><p>Beer-and-vodka-battered seasonal local fish, red cabbage, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Jerk Shrimp Taco</strong> <span>$5</span><p>Spicy slaw, pico de gallo, chipotle aioli, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Local Catch Taco</strong> <span>$4</span><p>Grilled seasonal local fish, red cabbage, pico de gallo, lime crema, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Roasted Cauliflower Taco</strong> <span>$4</span><p>Pickled onions, sweet soy, toasted sesame seeds, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Cheesy Mac</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Sautéed Spinach</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Cotija-Truffle Fries</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Black Beans</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Mashed Potatoes</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>White Rice</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Veggie Medley</strong> <span>$7</span><p>Side portion.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Gallo Pinto</strong> <span>$7</span><p>White rice, black beans, pico de gallo, cotija, and cilantro.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Poke Bowl</strong> <span>$26</span><p>Sushi rice, shredded carrots, cucumber, radish, marinated yellowfin tuna, and chipotle aioli.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Mediterranean Bowl</strong> <span>$21</span><p>House-made hummus, grilled halloumi, cherry tomato, radish, cucumber, red onion, roasted garlic oil, and naan.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Zuma Beach Bowl</strong> <span>$21</span><p>Quinoa, vegetable medley, crunchy chickpeas, pickled onions, and lemon-basil vinaigrette.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Miyazaki Bowl</strong> <span>$26</span><p>Crispy pork, steamed white rice, cucumber, red cabbage, wakame seaweed salad, rice-wine vinaigrette, and fried egg.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Beach Kebabs</strong> <span>$28</span><p>Jumbo shrimp skewers with coconut-chorizo rice.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Quesadilla</strong> <span>$12</span><p>Grilled flour tortilla, mixed cheeses, and pico de gallo.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Roasted Chicken</strong> <span>$26</span><p>Served with mac and cheese, sautéed spinach, diced tomatoes, and fine herbs.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Sirloin Steak</strong> <span>$31</span><p>Served with mashed potatoes, sautéed spinach, and frizzled onions.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Fish + Chips</strong> <span>$23</span><p>Beer-battered seasonal local fish with crispy fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Coconut-Crusted Cod</strong> <span>$29</span><p>White rice, iceberg lettuce, green apple, cucumber, and sweet chili sauce.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Lobster Roll</strong> <span>$35</span><p>Hot: warm and buttery. Cold: tossed in herb aioli. Served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Big John Burger</strong> <span>$15</span><p>Seven-ounce tri-cut beef blend served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Big Al Burger</strong> <span>$18</span><p>Seven-ounce tri-cut beef blend, American cheese, bacon, lettuce, tomato, and onion; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Korean Chicken Sammy</strong> <span>$16</span><p>Fried chicken breast, spicy kimchi, cucumber, honey-gochujang, sesame seeds, and buttermilk ranch; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Maverick Burger</strong> <span>$21</span><p>Seven-ounce tri-cut beef blend, A1 aioli, crispy shallots, pork carnitas, and pepper jack; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Shrimp Po Boy</strong> <span>$20</span><p>Coconut-milk-marinated fried shrimp, shredded lettuce, tomato, and fried jalapeños; served with fries.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Churros</strong> <span>$8</span><p>House-made churros with caramel and vanilla dipping sauces.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Ice Cream</strong> <span>$6</span><p>One scoop of vanilla ice cream.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li><li><strong>Key Lime Pie</strong> <span>$8</span><p>Tangy key lime custard, graham cracker crust, whipped cream, and lime zest.</p><p><small>Source status: approved</small></p><p><small>Allergy status: verification-required - use the current manager/kitchen verification chain.</small></p></li></ul></section><section class="curriculum-block curriculum-steps"><h2>Pass-to-table accuracy</h2><ol><li>Read full ticket and callouts</li><li>Match item, table, seat, and modifier</li><li>Stop for allergy verification</li><li>Carry safely and protect temperature</li><li>Announce the item clearly</li><li>Confirm missing/extra items</li><li>Return or hand off any issue by name</li></ol></section><section class="curriculum-block curriculum-practice"><h2>Runner rail</h2><p>Run a mixed rail with a modifier, allergy callout, missing side, and table-number variation.</p><h3>Success criteria</h3><ul><li>Ticket accuracy</li><li>Allergy stop point</li><li>Safe carry</li><li>Clear announcement</li><li>Missing item owned through closure</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 100%; practical required.</p><ol><li><strong>multiple-choice</strong>: What should happen when an allergy item reaches the pass without the required verification?</li><li><strong>practical</strong>: Pass the runner-rail practical.</li></ol></section><footer><small>Sources: food-menu-supplied, hospitality-reset-2026-08, allergy-source-current</small></footer></article>$curriculum_html$, 65, true, true, 50, ARRAY['support', 'runner', 'expo', 'branch-certification', 'practical-required']::text[]),
  ('cur-support-volume-system', 'sec-support-onboarding', 'Volume System: Priorities, Zones + 10 for 10', 'Stay urgent and calm by assigning zones, naming priorities, and resetting drift before it compounds.', 'support-volume-system', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-volume-system"><header><p class="curriculum-eyebrow">support / volume / teamwork / required</p><h1>Volume System: Priorities, Zones + 10 for 10</h1><p>Stay urgent and calm by assigning zones, naming priorities, and resetting drift before it compounds.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Choose the next highest-value action</li><li>Help without creating duplication</li><li>Use and receive a neutral reset</li></ul></section><section class="curriculum-block curriculum-steps"><h2>Priority ladder</h2><ol><li>Immediate safety/allergy risk</li><li>Hot food, kitchen bell, and ticket accuracy</li><li>Invisible arrival or direct guest need</li><li>Drink/water/table maintenance</li><li>Reset and readiness</li><li>Low-priority sidework</li></ol></section><section class="curriculum-block curriculum-standard curriculum-tone-orange"><h2>10 for 10</h2><p>When a zone drifts, anyone may call a roughly 30-second reset. Say Heard, join the reset, verify completion, recognize it, and return to service.</p></section><section class="curriculum-block curriculum-practice"><h2>Volume matrix</h2><p>Prioritize ten simultaneous cues, make two named handoffs, and complete one 10 for 10.</p><h3>Success criteria</h3><ul><li>Safety and hot food protected</li><li>No guest invisible</li><li>No duplicate ownership</li><li>Reset is fast and complete</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What beats low-priority sidework?</li><li><strong>practical</strong>: Complete the volume-matrix drill.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, leadership-os-1</small></footer></article>$curriculum_html$, 40, true, true, 60, ARRAY['support', 'volume', 'teamwork', 'required', 'practical-required']::text[]),
  ('cur-support-guest-questions-recovery', 'sec-support-onboarding', 'Guest Questions, Recovery + Strong Handoffs', 'Own the question without bluffing, pointing, or promising beyond the role.', 'support-guest-questions-recovery', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-guest-questions-recovery"><header><p class="curriculum-eyebrow">support / recovery / handoff / required</p><h1>Guest Questions, Recovery + Strong Handoffs</h1><p>Own the question without bluffing, pointing, or promising beyond the role.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Use &#039;let me confirm&#039; accurately</li><li>Complete warm transfers</li><li>Start L.A.S.T. and involve the right owner</li></ul></section><section class="curriculum-block curriculum-comparison"><h2>Own without inventing</h2><div class="curriculum-table-wrap"><table><thead><tr><th>Avoid</th><th>Use</th></tr></thead><tbody><tr><td>I do not know.</td><td>Let me confirm that so I give you the right answer.</td></tr><tr><td>Ask your server.</td><td>I can help with that. Let me bring your server over and explain what you need.</td></tr><tr><td>The kitchen is backed up.</td><td>Thank you for waiting. I am getting an exact update now.</td></tr></tbody></table></div></section><section class="curriculum-block curriculum-practice"><h2>Boundary reps</h2><p>Handle a menu question, allergy question, delayed item, and guest dislike from the support role.</p><h3>Success criteria</h3><ul><li>No guess</li><li>Correct owner</li><li>Warm transfer</li><li>Guest sees action</li><li>Follow-up closes loop</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 85%; practical required.</p><ol><li><strong>multiple-choice</strong>: What is the correct response when you do not know a menu answer?</li><li><strong>practical</strong>: Complete four boundary reps.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, allergy-source-current</small></footer></article>$curriculum_html$, 35, true, true, 70, ARRAY['support', 'recovery', 'handoff', 'required', 'practical-required']::text[]),
  ('cur-support-final-practical', 'sec-support-onboarding', 'Support Shared Core + Branch Practical', 'Prove the shared safety/hospitality core, then pass each assigned branch independently.', 'support-final-practical', $curriculum_html$<article class="curriculum-module" data-curriculum-module="cur-support-final-practical"><header><p class="curriculum-eyebrow">support / certification / final-practical / required</p><h1>Support Shared Core + Branch Practical</h1><p>Prove the shared safety/hospitality core, then pass each assigned branch independently.</p></header><section class="curriculum-block curriculum-outcomes"><h2>What you will prove</h2><ul><li>Pass shared core</li><li>Pass selected branch</li><li>Demonstrate consistent performance at 7/30-day audits</li></ul></section><section class="curriculum-block curriculum-field-assignment"><h2>Certification</h2><p>Complete the shared hospitality, safety, priorities, and handoff proof; then complete the Host, Busser, Food Runner/Expo, or Barback branch practical assigned by leadership.</p><h3>Success criteria</h3><ul><li>Shared core passes</li><li>Only observed branches are certified</li><li>No critical miss</li><li>7- and 30-day audit scheduled</li></ul></section><section class="curriculum-block curriculum-assessment"><h2>Assessment</h2><p>Passing score: 90%; practical required.</p><ol><li><strong>short-answer</strong>: Teach back CARE, priorities, safety stops, and closed-loop handoffs.</li><li><strong>practical</strong>: Complete shared core and selected branch practical.</li></ol></section><footer><small>Sources: hospitality-reset-2026-08, trainer-os-1</small></footer></article>$curriculum_html$, 75, true, true, 80, ARRAY['support', 'certification', 'final-practical', 'required', 'practical-required']::text[])
