INSERT INTO "TrainingPath" (id, title, description, "targetRole", "targetPositions", "moduleIntervalDays", "isActive") VALUES
  ('path-hospitality-reset', 'The Ditch Hospitality Reset', 'Every guest. Every shift. Every Ditch.', 'ALL_TEAM', ARRAY[]::text[], 1, true),
