INSERT INTO "QuizQuestion" (id, "quizId", "questionText", "questionType", options, "correctAnswer", explanation, "sortOrder") VALUES
  ('reset-care-1', 'quiz-cur-reset-promise-care', 'A guest is searching the room while you are carrying menus to another table. What is the first CARE move?', 'MULTIPLE_CHOICE', '["Finish every current task before reacting","Catch the cue and acknowledge the guest","Point toward their server","Wait for the guest to ask"]'::jsonb, 'Catch the cue and acknowledge the guest', 'Acknowledge immediately, then act or make a named handoff.', 1),
  ('reset-baseline-1', 'quiz-cur-reset-baseline-magic', 'A personalized guest moment counts as great hospitality even if another arrival remains invisible.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'False', 'The baseline belongs to every guest before magic is added for one guest.', 1),
  ('reset-room-1', 'quiz-cur-reset-whole-room', 'A request you cannot personally complete is finished when...', 'MULTIPLE_CHOICE', '["You point toward the right station","You tell any nearby teammate","A named owner accepts it and you verify the loop","The guest stops asking"]'::jsonb, 'A named owner accepts it and you verify the loop', 'Review the approved curriculum source and run the practical rep.', 1),
  ('reset-source-1', 'quiz-cur-reset-source-safety', 'A guest asks whether a dish is safe for a serious allergy and you remember an ingredient list. What should you do?', 'MULTIPLE_CHOICE', '["Answer from memory","Read the menu description","Use the current allergy chain and let the kitchen verify","Say every dish has cross-contact and stop"]'::jsonb, 'Use the current allergy chain and let the kitchen verify', 'Review the approved curriculum source and run the practical rep.', 1),
  ('reset-last-1', 'quiz-cur-reset-last', 'When does the Think step happen?', 'MULTIPLE_CHOICE', '["Before listening","While debating the facts","After the guest is cared for","Only at the monthly meeting"]'::jsonb, 'After the guest is cared for', 'Review the approved curriculum source and run the practical rep.', 1),
  ('reset-account-1', 'quiz-cur-reset-accountability', 'What is the first response to a valid in-the-moment correction?', 'MULTIPLE_CHOICE', '["Explain the context","Point out who else missed","Heard, then correct it","Wait until after the shift"]'::jsonb, 'Heard, then correct it', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-0-knowledge', 'quiz-cur-leadership-week-0', 'What makes a Culture Audit score usable?', 'MULTIPLE_CHOICE', '["A leader''s general feeling","An observed example tied to a standard","The employee''s intention","The restaurant''s best shift"]'::jsonb, 'An observed example tied to a standard', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-1-knowledge', 'quiz-cur-leadership-week-1', 'Which sequence is the leadership standard?', 'MULTIPLE_CHOICE', '["Mandate, assume, criticize, move on","Model, inspect, coach, reinforce","Delegate, disappear, review monthly","Motivate, celebrate, avoid correction"]'::jsonb, 'Model, inspect, coach, reinforce', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-2-knowledge', 'quiz-cur-leadership-week-2', 'What is the purpose of 10 for 10?', 'MULTIPLE_CHOICE', '["Punish a messy employee","Create a neutral, fast return to standard","Replace the closing checklist","Give the manager a break"]'::jsonb, 'Create a neutral, fast return to standard', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-3-knowledge', 'quiz-cur-leadership-week-3', 'What converts awareness into hospitality?', 'MULTIPLE_CHOICE', '["A positive attitude alone","A specific action that improves the moment","Waiting for a request","A discount"]'::jsonb, 'A specific action that improves the moment', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-4-knowledge', 'quiz-cur-leadership-week-4', 'What should happen before a recommendation?', 'MULTIPLE_CHOICE', '["Name the most expensive item","Ask enough to understand the guest","List every special","Promise the guest will love it"]'::jsonb, 'Ask enough to understand the guest', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-5-knowledge', 'quiz-cur-leadership-week-5', 'What does L.A.S.T. stand for?', 'MULTIPLE_CHOICE', '["Listen, Apologize, Solve, Think","Learn, Ask, Sell, Thank","Look, Act, Support, Transfer","Listen, Agree, Stop, Talk"]'::jsonb, 'Listen, Apologize, Solve, Think', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-6-knowledge', 'quiz-cur-leadership-week-6', 'Which opening is behavioral coaching?', 'MULTIPLE_CHOICE', '["You are lazy","You do not care","I watched three food runs sit while you were available","Your attitude is the problem"]'::jsonb, 'I watched three food runs sit while you were available', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-7-knowledge', 'quiz-cur-leadership-week-7', 'What should an employee bring upward with a non-urgent problem?', 'MULTIPLE_CHOICE', '["Only the complaint","Facts, actions tried, options, and a recommendation","A list of who caused it","Nothing until it becomes urgent"]'::jsonb, 'Facts, actions tried, options, and a recommendation', 'Review the approved curriculum source and run the practical rep.', 1),
  ('leadership-week-8-knowledge', 'quiz-cur-leadership-week-8', 'Which element proves a system happened correctly?', 'MULTIPLE_CHOICE', '["Intention","Verification","A reminder","A strong manager"]'::jsonb, 'Verification', 'Review the approved curriculum source and run the practical rep.', 1),
  ('trainer-identity-1', 'quiz-cur-trainer-identity-selection', 'What qualifies a person to train independently?', 'MULTIPLE_CHOICE', '["Tenure","Fast technical performance","Leadership certification backed by transfer proof","Popularity with the team"]'::jsonb, 'Leadership certification backed by transfer proof', 'Review the approved curriculum source and run the practical rep.', 1),
  ('trainer-method-1', 'quiz-cur-trainer-seven-step-method', 'What comes after a coached miss?', 'MULTIPLE_CHOICE', '["A long explanation","An immediate second take","Certification","A different trainer"]'::jsonb, 'An immediate second take', 'Review the approved curriculum source and run the practical rep.', 1),
  ('trainer-autonomy-1', 'quiz-cur-trainer-shift-autonomy', 'A training calendar date is enough reason to certify a skill.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'False', 'The calendar schedules opportunity; evidence determines advancement.', 1),
  ('trainer-coach-1', 'quiz-cur-trainer-coaching-learning', 'What proves a coaching conversation worked?', 'MULTIPLE_CHOICE', '["The trainee says yes","The trainer explains longer","The next rep changes","The manager agrees"]'::jsonb, 'The next rep changes', 'Review the approved curriculum source and run the practical rep.', 1),
  ('trainer-cert-1', 'quiz-cur-trainer-certification-audit', 'Which proof is unique to trainer certification?', 'MULTIPLE_CHOICE', '["Attendance","Knowledge","Transfer proof","Tenure"]'::jsonb, 'Transfer proof', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-identity-1', 'quiz-cur-server-identity-readiness', 'What is the server''s highest responsibility?', 'MULTIPLE_CHOICE', '["Take orders quickly","Own the guest''s experience and handoffs","Stay only in the assigned section","Sell the highest-priced item"]'::jsonb, 'Own the guest''s experience and handoffs', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-journey-1', 'quiz-cur-server-guest-journey', 'When should a delay be communicated?', 'MULTIPLE_CHOICE', '["After the guest asks twice","As soon as the server knows enough to give an honest update","Only when the manager arrives","At payment"]'::jsonb, 'As soon as the server knows enough to give an honest update', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-food-1', 'quiz-cur-server-food-menu', 'Where is the Quesadilla listed on the supplied current dining menu?', 'MULTIPLE_CHOICE', '["Tacos","Bowls","Platos","Dessert"]'::jsonb, 'Platos', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-bev-1', 'quiz-cur-server-beverage-menu', 'Which current drink is the classic, bright starting point?', 'MULTIPLE_CHOICE', '["Hang 10","Smoke on the Bay","Mo Pain Yo","Oaxaca Mule"]'::jsonb, 'Hang 10', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-sell-1', 'quiz-cur-server-passion-selling', 'What is the best response to ''What''s good?''', 'MULTIPLE_CHOICE', '["Everything","The most expensive thing","Ask one preference question, then take a position","Read every special"]'::jsonb, 'Ask one preference question, then take a position', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-pos-1', 'quiz-cur-server-pos-pacing-safety', 'What must happen in addition to marking an allergy in the POS?', 'MULTIPLE_CHOICE', '["Nothing","Verbal communication, manager involvement, and kitchen verification","Tell the guest it is probably safe","Ask another server"]'::jsonb, 'Verbal communication, manager involvement, and kitchen verification', 'Review the approved curriculum source and run the practical rep.', 1),
  ('server-recovery-1', 'quiz-cur-server-recovery-payment', 'What comes after a recovery solution?', 'MULTIPLE_CHOICE', '["Avoid the table","Specific follow-up","Only remove the item","Explain who caused it"]'::jsonb, 'Specific follow-up', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-identity-1', 'quiz-cur-bartender-identity-journey', 'What is the acknowledgment target at the bar?', 'MULTIPLE_CHOICE', '["30 seconds","90 seconds","When the ticket rail is empty","After the guest waves"]'::jsonb, '30 seconds', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-safe-1', 'quiz-cur-bartender-safe-responsible', 'Security checking an ID removes the bartender''s responsibility.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'False', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-technique-1', 'quiz-cur-bartender-station-technique', 'When is carbonation normally added?', 'MULTIPLE_CHOICE', '["Before shaking","After shaking or stirring","With the base spirit","It does not matter"]'::jsonb, 'After shaking or stirring', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-marg-1', 'quiz-cur-bartender-approved-signatures-1', 'Which verified spicy marg uses both jalapeño and habanero?', 'MULTIPLE_CHOICE', '["Hang 10","Smoke on the Bay","Holla Pain Yo!","Mo Pain Yo!"]'::jsonb, 'Mo Pain Yo!', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-house-1', 'quiz-cur-bartender-approved-signatures-2', 'Which approved cocktail is topped with ginger beer after double straining?', 'MULTIPLE_CHOICE', '["Oaxaca Mule","Mojito","Hang 10","Cool as a Cucumber"]'::jsonb, 'Oaxaca Mule', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-pair-1', 'quiz-cur-bartender-passion-pairing', 'What pairing reason is listed for Hang 10 with fried or rich food?', 'MULTIPLE_CHOICE', '["Smoke mirrors char","Lime and salt wake up the food","Coconut adds richness","Ginger adds heat"]'::jsonb, 'Lime and salt wake up the food', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-flow-1', 'quiz-cur-bartender-ticket-recovery', 'What protects speed most reliably?', 'MULTIPLE_CHOICE', '["Free-pouring","Skipping reset","Organized station and exact repeatable method","Ignoring guests until rail is clear"]'::jsonb, 'Organized station and exact repeatable method', 'Review the approved curriculum source and run the practical rep.', 1),
  ('bartender-close-1', 'quiz-cur-bartender-open-close-control', 'Initialing a checklist means you completed or physically verified the work.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'True', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-core-1', 'quiz-cur-support-shared-core', 'Certification in one support branch automatically certifies every branch.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'False', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-safety-1', 'quiz-cur-support-safety-map', 'What should a support handoff include?', 'MULTIPLE_CHOICE', '["A general call to the room","A name, exact action, confirmation, and follow-up","A point toward the station","Only the table number"]'::jsonb, 'A name, exact action, confirmation, and follow-up', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-host-1', 'quiz-cur-support-host-branch', 'A guest may wait during volume, but should never...', 'MULTIPLE_CHOICE', '["Ask a question","Feel invisible","Receive an update","See the host help another guest"]'::jsonb, 'Feel invisible', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-busser-1', 'quiz-cur-support-busser-branch', 'A reset is complete once the tabletop is wiped.', 'TRUE_FALSE', '["True","False"]'::jsonb, 'False', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-runner-1', 'quiz-cur-support-runner-branch', 'What should happen when an allergy item reaches the pass without the required verification?', 'MULTIPLE_CHOICE', '["Run it quickly","Pause and involve the required manager/kitchen verification","Ask the guest","Remove the garnish"]'::jsonb, 'Pause and involve the required manager/kitchen verification', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-volume-1', 'quiz-cur-support-volume-system', 'What beats low-priority sidework?', 'MULTIPLE_CHOICE', '["Reorganizing straws","Food in the pass and a waiting guest","Polishing an unused shelf","A long teammate conversation"]'::jsonb, 'Food in the pass and a waiting guest', 'Review the approved curriculum source and run the practical rep.', 1),
  ('support-recovery-1', 'quiz-cur-support-guest-questions-recovery', 'What is the correct response when you do not know a menu answer?', 'MULTIPLE_CHOICE', '["Guess confidently","Say it is probably fine","Confirm from the approved source/right person and return","Point at the menu"]'::jsonb, 'Confirm from the approved source/right person and return', 'Review the approved curriculum source and run the practical rep.', 1);

